function ipaIsClientAuthenticated(){
 const u=window.IPAFirebase?.user;
 return !!(u && u.uid!=='5dlGX6JlrUQHyjFWSHB9Dye0r1E3');
}
function ipaClientDisplayName(){
 const d=ipaDB(); const u=window.IPAFirebase?.user;
 const email=String(u?.email||'').toLowerCase();
 const c=(d?.clients||[]).find(x=>x.authUid===u?.uid||String(x.email||'').toLowerCase()===email)||d?.client||{};
 return c.name||c.clientName||u?.displayName||String(u?.email||'Viajante').split('@')[0];
}
function ipaUpdateProfileButton(){
 const b=document.querySelector('#profileBtn'); if(!b)return;
 if(state.profile!=='client'||!ipaIsClientAuthenticated()){b.hidden=true;b.textContent='';return;}
 const name=ipaClientDisplayName();
 const initials=String(name).trim().split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'👤';
 b.hidden=false;b.innerHTML=`${ipaEscape(initials)}<span></span>`;b.setAttribute('aria-label',`Perfil de ${name}`);
}
// Preserve scroll for updates within the same screen (Firebase refreshes,
// checklist actions, day selection, etc.). Reset only on real navigation.
let ipaLastRenderedScreen=null;
function render(){
 if(state.profile==='client' && state.scenarioChosen && !ipaIsClientAuthenticated()){
   ipaUpdateProfileButton(); showClientLogin(); return;
 }
 const screen=state.profile+':'+state.route;
 const sameScreen=ipaLastRenderedScreen===screen;
 const previousY=Math.max(0,window.scrollY||document.documentElement.scrollTop||0);
 topTitle.textContent=titles[state.route]||'Indo por Aí';
 view.innerHTML=routes[state.route]();
 document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.route===state.route));
 document.body.classList.toggle('hidden-nav',state.profile==='prospect');
 bind();
 ipaUpdateProfileButton();
 if(state.route==='admin'&&state.profile==='admin')ipaEnsureAdminConciergeListener();
 ipaLastRenderedScreen=screen;
 // Avoid scrolling to the top on every background update.
 // Restoring after layout avoids jumps when content is re-rendered.
 if(sameScreen){
   window.scrollTo({top:previousY,behavior:'instant'});
   requestAnimationFrame(()=>window.scrollTo({top:previousY,behavior:'instant'}));
 }else if(previousY>0){
   window.scrollTo({top:0,behavior:'instant'});
 }
 if(state.profile==='client'&&state.scenarioChosen)
   requestAnimationFrame(ipaSaveClientPage);
}

function ipaParticipantKey(p){return p?.id||p?.participantId||p?.email||p?.name||''}
function ipaParticipantStatusLabel(v){return v==='accepted'?'✅ Aceito':v==='sent'?'📨 Enviado':'⏳ Pendente'}
function ipaEnsureParticipants(t){
  if(!Array.isArray(t.participants)) t.participants=[];
  return t.participants;
}
function ipaCurrentUserEmail(){
  try{return window.IPAFirebase?.user?.email||window.state?.user?.email||''}catch(e){return ''}
}
function ipaCurrentParticipant(t){
  const email=(ipaCurrentUserEmail()||'').toLowerCase();
  return (t?.participants||[]).find(p=>(p.email||'').toLowerCase()===email || p.authUid===window.IPAFirebase?.user?.uid) || null;
}
function ipaParticipantBadge(t){
  const p=ipaCurrentParticipant(t);
  return p?`<span class="ipa-participant-badge">👤 ${p.name||p.email}</span>`:'';
}
function ipaParticipantAdminSection(t){
  const ps=ipaEnsureParticipants(t);
  return `<section class="admin-card ipa-participants-admin">
    <div class="admin-card-head"><div><span class="eyebrow">👥 PARTICIPANTES</span><h3>Viajantes desta viagem</h3></div><button class="btn btn-primary" data-admin-add-participant>+ Adicionar</button></div>
    <div class="ipa-participant-list">${ps.length?ps.map((p,i)=>`<div class="ipa-participant-row">
      <div><b>${p.name||'Participante'}</b><small>${p.email||''}${p.seat?` · Assento ${p.seat}`:''}${p.isMinor?' · Menor':''}${p.isPrimary?' · Titular':''}</small></div>
      <span>${ipaParticipantStatusLabel(p.status)}</span>
      <button class="btn btn-ghost" data-admin-send-participant="${i}">Enviar convite</button>
    </div>`).join(''):'<p class="muted">Nenhum participante cadastrado.</p>'}</div>
  </section>`;
}
function ipaOpenParticipantModal(t){
  const o=modal(`<h2>👥 Adicionar participante</h2>
    <input class="ipa-p-name" placeholder="Nome completo">
    <input class="ipa-p-email" placeholder="E-mail">
    <input class="ipa-p-seat" placeholder="Assento (opcional)">
    <label><input class="ipa-p-primary" type="checkbox"> Titular da viagem</label>
    <label><input class="ipa-p-minor" type="checkbox"> Menor de idade</label>
    <input class="ipa-p-resp" placeholder="Responsável (se menor)">
    <button class="btn btn-primary ipa-p-save">Salvar participante</button>`);
  o.querySelector('.ipa-p-save').onclick=async()=>{
    const name=o.querySelector('.ipa-p-name').value.trim(),email=o.querySelector('.ipa-p-email').value.trim().toLowerCase();
    if(!name || (!email && !o.querySelector('.ipa-p-minor').checked))return alert('Informe nome e e-mail, ou marque como menor.');
    const p={id:'p-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),tripId:t.id,name,email,seat:o.querySelector('.ipa-p-seat').value.trim(),
      isPrimary:o.querySelector('.ipa-p-primary').checked,isMinor:o.querySelector('.ipa-p-minor').checked,responsible:o.querySelector('.ipa-p-resp').value.trim(),
      status:o.querySelector('.ipa-p-minor').checked?'accepted':'pending',createdAt:new Date().toISOString()};
    ipaEnsureParticipants(t).push(p);
    if(window.IPAData?.updateTrip) window.IPAData.updateTrip(t.id,{participants:t.participants});
    try{await window.IPAFirebase?.syncNow?.()}catch(e){}
    o.remove(); try{render()}catch(e){}
  };
}
async function ipaSendParticipantInvite(t,index){
  const p=t.participants?.[index]; if(!p || p.isMinor)return;
  const token=btoa(unescape(encodeURIComponent(JSON.stringify({tripId:t.id,participantId:p.id,email:p.email})))).replace(/=+$/,'');
  p.inviteToken=token;p.status='sent';p.invitedAt=new Date().toISOString();
  if(window.IPAData?.updateTrip) window.IPAData.updateTrip(t.id,{participants:t.participants});
  try{await window.IPAFirebase?.syncNow?.()}catch(e){}
  const link=`${location.origin}${location.pathname}?invite=${encodeURIComponent(token)}`;
  try{await navigator.clipboard.writeText(link);alert('Convite vinculado à viagem copiado para a área de transferência.');}
  catch(e){prompt('Copie o link do convite:',link)}
  try{render()}catch(e){}
}
function ipaResolveInviteFromUrl(){
  const q=new URLSearchParams(location.search),tok=q.get('invite'); if(!tok)return null;
  try{
    const json=decodeURIComponent(escape(atob(tok.replace(/-/g,'+').replace(/_/g,'/'))));
    return JSON.parse(json);
  }catch(e){return null}
}
function ipaApplyInviteBinding(){
  const inv=ipaResolveInviteFromUrl(); if(!inv)return;
  try{
    const trips=window.IPAData?.getTrips?.()||ipaDB()?.trips||[];
    const t=trips.find(x=>x.id===inv.tripId); if(!t)return;
    const p=(t.participants||[]).find(x=>x.id===inv.participantId); if(!p)return;
    const email=(ipaCurrentUserEmail()||'').toLowerCase();
    if(email && p.email && email!==p.email.toLowerCase())return;
    p.status='accepted'; p.authUid=window.IPAFirebase?.user?.uid||p.authUid; p.acceptedAt=new Date().toISOString();
    if(window.IPAData?.setActiveTrip) window.IPAData.setActiveTrip(t.id);
    else {try{localStorage.setItem('ipa-active-trip',t.id)}catch(e){}}
    if(window.IPAData?.updateTrip) window.IPAData.updateTrip(t.id,{participants:t.participants});
    try{window.IPAFirebase?.syncNow?.()}catch(e){}
    history.replaceState({},'',location.pathname);
  }catch(e){console.warn('Convite',e)}
}
window.ipaCurrentParticipant=ipaCurrentParticipant;
window.ipaApplyInviteBinding=ipaApplyInviteBinding;

function ipaSafeKey(v){return String(v||'sem-id').replace(/[^a-zA-Z0-9._-]/g,'_')}
function ipaCurrentClientId(){
  try{
    const t=window.IPAData?.getActiveTrip?.();
    return t?.clientId || t?.client?.id || window.IPAData?.getActiveClient?.()?.id || window.state?.client?.id || '';
  }catch(e){return ''}
}
async function ipaUploadMemoryFile(file, tripId, momentId){
  const fb=window.IPAFirebase;
  if(!fb?.storage || !fb?.ref || !fb?.uploadBytes || !fb?.getDownloadURL) throw new Error('Firebase Storage indisponível');
  const clientId=ipaCurrentClientId();
  if(!clientId) throw new Error('clientId não encontrado para upload');
  const ext=(file.name||'arquivo').split('.').pop();
  const fileName=`${ipaSafeKey(momentId)}-${Date.now()}.${ipaSafeKey(ext)}`;
  const path=`memories/${ipaSafeKey(clientId)}/${ipaSafeKey(tripId)}/${fileName}`;
  const storageRef=fb.ref(fb.storage,path);
  await fb.uploadBytes(storageRef,file,{contentType:file.type||'application/octet-stream'});
  const url=await fb.getDownloadURL(storageRef);
  return {url,path,clientId,fileName};
}
async function ipaPersistMemoryMeta(moment){
  try{
    const d=ipaDB(); d.memories=d.memories||[];
    const idx=d.memories.findIndex(x=>x.id===moment.id);
    if(idx>=0)d.memories[idx]=moment; else d.memories.push(moment);
    saveDB(d);
  }catch(e){console.warn('Falha local memory meta',e)}
  try{if(window.IPAFirebase?.syncNow) await window.IPAFirebase.syncNow()}catch(e){console.warn('Falha sync Firestore',e)}
}
window.ipaCurrentClientId=ipaCurrentClientId;
window.ipaUploadMemoryFile=ipaUploadMemoryFile;
window.ipaPersistMemoryMeta=ipaPersistMemoryMeta;
async function ipaSaveTemplateBuilder(){
 const save=document.querySelector('#saveTemplate');
 try{
  const name=document.querySelector('#templateName')?.value?.trim()||'';
  const destination=document.querySelector('#templateDestination')?.value?.trim()||'';
  const description=document.querySelector('#templateDescription')?.value?.trim()||'';
  const dayCount=Math.max(1,Number(document.querySelector('#templateDays')?.value||1));
  if(!name){toast('Informe o nome do roteiro');return false}
  if(!destination){toast('Informe o destino');return false}
  const selected=[...document.querySelectorAll('[data-template-place]:checked')];
  if(!selected.length){toast('Selecione pelo menos um lugar');return false}
  const places=adminData().placeCatalog||[];
  const itinerary=Array.from({length:dayCount},(_,i)=>({day:i+1,title:`Dia ${i+1}`,places:[]}));
  const daySelectors=[...document.querySelectorAll('[data-template-day]')];
  selected.forEach((x,idx)=>{
   const catalogId=String(x.getAttribute('data-template-place')||'');
   const place=places.find(p=>String(p.id)===catalogId);
   if(!place)return;
   const daySelect=daySelectors.find(sel=>String(sel.getAttribute('data-template-day'))===catalogId);
   const dayNo=Math.min(dayCount,Math.max(1,Number(daySelect?.value||1)));
   itinerary[dayNo-1].places.push({...place,id:`place-${Date.now()}-${idx}-${Math.random().toString(36).slice(2,6)}`,catalogPlaceId:place.id});
  });
  const totalPlaces=itinerary.reduce((n,d)=>n+d.places.length,0);
  if(!totalPlaces){toast('Não consegui ler os lugares selecionados');return false}
  if(save){save.disabled=true;save.textContent='Salvando roteiro...'}
  const allChosen=itinerary.flatMap(d=>d.places);
  const estimatedCost=allChosen.reduce((n,p)=>n+Number(p.cost||0),0);
  const created=IPAData.createItineraryTemplate({name,destination,description,days:dayCount,itinerary,estimatedCost,currency:allChosen.find(p=>p.currency)?.currency||'EUR',generatedFromCatalog:true});
  if(!created)throw new Error('Não foi possível criar o roteiro');
  toast(`Roteiro salvo com ${totalPlaces} lugar${totalPlaces>1?'es':''} ✓`);
  modal.close();
  adminSection='templates';
  render();
  if(window.IPAFirebase?.user)window.IPAFirebase.syncNow().catch(e=>console.warn('Roteiro salvo; sincronização pendente',e));
  return true;
 }catch(e){
  console.error('ipaSaveTemplateBuilder',e);
  if(save){save.disabled=false;save.textContent='Salvar roteiro'}
  toast(e.message||'Não foi possível salvar o roteiro');
  return false;
 }
}
window.ipaSaveTemplateBuilder=ipaSaveTemplateBuilder;

function ipaTemplateBuilderSelected(){
 const places=adminData().placeCatalog||[];
 const dayCount=Math.max(1,Number(document.querySelector('#templateDays')?.value||1));
 const daySelectors=[...document.querySelectorAll('[data-template-day]')];
 return [...document.querySelectorAll('[data-template-place]:checked')].map(x=>{
  const id=String(x.getAttribute('data-template-place')||'');
  const place=places.find(p=>String(p.id)===id);
  const daySel=daySelectors.find(sel=>String(sel.getAttribute('data-template-day'))===id);
  return place?{...place,_day:Math.min(dayCount,Math.max(1,Number(daySel?.value||1)))}:null;
 }).filter(Boolean);
}
function ipaDistanceKm(a,b){
 const lat1=Number(a?.lat),lon1=Number(a?.lng),lat2=Number(b?.lat),lon2=Number(b?.lng);
 if(![lat1,lon1,lat2,lon2].every(Number.isFinite))return Infinity;
 const R=6371,toRad=x=>x*Math.PI/180,dLat=toRad(lat2-lat1),dLon=toRad(lon2-lon1);
 const q=Math.sin(dLat/2)**2+Math.cos(toRad(lat1))*Math.cos(toRad(lat2))*Math.sin(dLon/2)**2;
 return 2*R*Math.asin(Math.sqrt(q));
}
function ipaOptimizeTemplateBuilder(){
 const selected=ipaTemplateBuilderSelected();
 if(selected.length<2){toast('Selecione pelo menos 2 lugares');return}
 const dayCount=Math.max(1,Number(document.querySelector('#templateDays')?.value||1));
 const geo=selected.filter(p=>Number.isFinite(Number(p.lat))&&Number.isFinite(Number(p.lng)));
 if(geo.length<2){toast('Cadastre pelo menos 2 lugares com localização do Google para otimizar');return}
 const ordered=[];let remaining=[...geo],cur=remaining.shift();ordered.push(cur);
 while(remaining.length){remaining.sort((a,b)=>ipaDistanceKm(cur,a)-ipaDistanceKm(cur,b));cur=remaining.shift();ordered.push(cur)}
 // Distribui em blocos geograficamente próximos pelos dias, respeitando a ordem otimizada.
 const per=Math.ceil(ordered.length/dayCount);
 const selectors=[...document.querySelectorAll('[data-template-day]')];
 ordered.forEach((p,i)=>{const sel=selectors.find(x=>String(x.getAttribute('data-template-day'))===String(p.id));if(sel)sel.value=Math.min(dayCount,Math.floor(i/per)+1)});
 ipaRefreshTemplateBuilder();
 toast('Roteiro reorganizado por proximidade ✓');
}
function ipaRefreshTemplateBuilder(){
 const places=adminData().placeCatalog||[],days=document.querySelector('#templateDays'),summary=document.querySelector('#templateSelectionSummary');
 const max=Math.max(1,Number(days?.value||1));
 document.querySelectorAll('[data-template-day]').forEach(sel=>{[...sel.options].forEach(o=>o.hidden=Number(o.value)>max);if(Number(sel.value)>max)sel.value=max});
 const selected=ipaTemplateBuilderSelected();
 const total=selected.reduce((sum,p)=>sum+Number(p.cost||0),0);
 const currency=selected.find(p=>p.currency)?.currency||'EUR';
 if(summary)summary.innerHTML=`<b>${selected.length} lugares selecionados</b><span>custo base ${ipaCatalogMoney(total,currency)} por pessoa</span>`;
 const preview=document.querySelector('#templateVisualPreview');
 if(preview){preview.innerHTML=Array.from({length:max},(_,i)=>{const list=selected.filter(p=>p._day===i+1);return `<div class="builder-day"><div class="builder-day-head"><strong>Dia ${i+1}</strong><small>${list.length} lugar${list.length===1?'':'es'}</small></div>${list.map(p=>`<div class="builder-place"><span>${p.category==='Gastronomia'?'🍴':p.category==='Natureza'?'🌿':'📍'}</span><div><b>${ipaEscape(p.name)}</b><small>${ipaEscape([p.city,p.category].filter(Boolean).join(' · '))}</small></div><em>${ipaCatalogMoney(p.cost,p.currency||currency)}</em></div>`).join('')||'<small class="builder-empty">Arraste sua seleção para este dia usando o seletor ao lado de cada lugar.</small>'}</div>`}).join('')}
 const budget=Number(document.querySelector('#templateBudget')?.value||0),budgetBox=document.querySelector('#templateBudgetStatus');
 if(budgetBox){const left=budget-total;budgetBox.className='template-budget-status '+(budget&&left<0?'over':'ok');budgetBox.innerHTML=budget?`<span>Orçamento: <b>${ipaCatalogMoney(budget,currency)}</b></span><span>Roteiro: <b>${ipaCatalogMoney(total,currency)}</b></span><span>${left>=0?`Disponível: <b>${ipaCatalogMoney(left,currency)}</b>`:`Excedido: <b>${ipaCatalogMoney(Math.abs(left),currency)}</b>`}</span>`:'<span>Informe um orçamento para acompanhar o custo do roteiro.</span>'}
 const why=document.querySelector('#templateWhy');
 if(why){const interests=[...new Set(selected.flatMap(p=>p.interests||[]))].slice(0,3);const imperdiveis=selected.filter(p=>p.priority==='Imperdível').length;why.textContent=selected.length?`Este roteiro combina ${selected.length} experiências da curadoria${interests.length?`, com foco em ${interests.join(', ')}`:''}${imperdiveis?` e ${imperdiveis} destaque${imperdiveis>1?'s':''} imperdível${imperdiveis>1?'eis':''}`:''}. A distribuição pode ser otimizada por proximidade.`:'Selecione lugares para ver por que este roteiro combina com o perfil da viagem.'}
}


function ipaNormText(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim()}
function ipaFindCatalogDuplicates(name,city,excludeId=''){
 const n=ipaNormText(name),c=ipaNormText(city);if(!n)return [];
 return (adminData().placeCatalog||[]).filter(p=>String(p.id)!==String(excludeId)&&(!c||ipaNormText(p.city)===c)&&(ipaNormText(p.name)===n||ipaNormText(p.name).includes(n)||n.includes(ipaNormText(p.name))));
}
async function ipaLocateCatalogPlace(p){
 const q=[p.name,p.address].filter(Boolean).join(' '),destination=[p.city,p.country].filter(Boolean).join(', ');
 const r=await fetch(`/api/places/search?q=${encodeURIComponent(q)}&destination=${encodeURIComponent(destination)}`,{cache:'no-store'}),j=await r.json();
 if(!r.ok||!j.ok)throw new Error(j.error||'Não foi possível localizar');
 const hit=(j.places||[])[0];if(!hit||!Number.isFinite(Number(hit.lat))||!Number.isFinite(Number(hit.lng)))throw new Error('Local não encontrado com segurança');
 IPAData.updateCatalogPlace(p.id,{lat:Number(hit.lat),lng:Number(hit.lng),placeId:p.placeId||hit.id||'',photoUrl:p.photoUrl||hit.photoUrl||'',mapsUrl:p.mapsUrl||hit.mapsUrl||'',address:p.address||hit.address||'',geoUpdatedAt:new Date().toISOString()});return hit;
}
// Beta 6.29.59 - busca cuidadosa, em lotes, de fotos para o acervo já cadastrado.
let ipaCatalogPhotoJob=null;
function ipaCatalogPhotoCount(){
 const arr=adminData().placeCatalog||[];
 return {total:arr.length,missing:arr.filter(p=>!p.photoUrl).length,pending:arr.filter(p=>!p.photoUrl&&p.photoLookupStatus!=='not-found').length};
}
function ipaCatalogPhotoFeedback(job){
 const el=document.querySelector('#catalogPhotoProgress');if(!el)return;
 const remaining=ipaCatalogPhotoCount().pending;
 el.hidden=false;
 el.innerHTML=`<div class="ipa-photo-job-head"><strong>${job.running?'Buscando fotos no Google…':job.paused?'Atualização interrompida':'Lote finalizado'}</strong><span>${job.done}/${job.total} pesquisados</span></div><div class="ipa-photo-job-bar"><div style="width:${job.total?Math.round(100*job.done/job.total):0}%"></div></div><small>✓ ${job.found} fotos gravadas · ${job.noPhoto} sem correspondência/foto · ${job.errors} erros · ${remaining} lugares ainda pendentes de busca</small><small>${ipaEscape(job.current||'')}</small>`;
 const btn=document.querySelector('#catalogPhotoStop');if(btn)btn.disabled=!job.running;
}
function ipaCatalogPhotoMatch(place,results){
 const n=ipaNormText(place.name), city=ipaNormText(place.city), country=ipaNormText(place.country);
 if(!n)return null;
 if(place.placeId){const exact=results.find(p=>p.id===place.placeId&&p.photoUrl);if(exact)return exact;}
 const scored=results.filter(p=>p.photoUrl).map(p=>{
  const m=ipaNormText(p.name), addr=ipaNormText(p.address),cityHit=!city||ipaNormText(p.city)===city||addr.includes(city);
  const countryHit=!country||ipaNormText(p.country)===country||addr.includes(country);
  const same=m===n,similar=m.length>8&&n.length>8&&(m.includes(n)||n.includes(m));
  return {p,valid:countryHit&&cityHit&&(same||similar),score:same?2:1};
 }).filter(x=>x.valid).sort((a,b)=>b.score-a.score);
 // Não escolher um local ambíguo caso a busca retorne duplicatas plausíveis.
 if(scored.length>1&&scored[0].score===scored[1].score)return null;
 return scored[0]?.p||null;
}
async function ipaCatalogPhotoLookup(place){
 if(place.placeId){
  const r=await fetch('/api/places/photo-info?placeId='+encodeURIComponent(place.placeId),{cache:'no-store'});
  const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Falha ao consultar foto pelo ID');
  if(j.photoUrl)return j;
 }
 const q=[place.name,place.address].filter(Boolean).join(' ').slice(0,190);
 const dest=[place.city,place.country].filter(Boolean).join(', ');
 const r=await fetch(`/api/places/search?q=${encodeURIComponent(q)}&destination=${encodeURIComponent(dest)}`,{cache:'no-store'});
 const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Falha ao pesquisar Google Places');
 return ipaCatalogPhotoMatch(place,j.places||[]);
}
// Sincroniza URLs de fotos já existentes no catálogo com os roteiros publicados.
// O cliente não tem permissão de leitura da coleção placeCatalog.
function ipaPhotoCatalogMatch(p,catalog){
 const id=String(p?.catalogPlaceId||p?.catalogId||'');
 if(id){const hit=catalog.find(x=>String(x.id)===id);if(hit)return hit}
 const pid=String(p?.placeId||'');
 if(pid){const hit=catalog.find(x=>x.placeId&&String(x.placeId)===pid);if(hit)return hit}
 const name=ipaNormText(p?.name),address=ipaNormText(p?.address);
 if(!name)return null;
 const matches=catalog.filter(x=>ipaNormText(x.name)===name);
 if(matches.length===1)return matches[0]; // unique name across catalog
 if(address){
  const exact=matches.filter(x=>ipaNormText(x.address)===address);
  if(exact.length===1)return exact[0];
  const cityMatched=matches.filter(x=>{
   const city=ipaNormText(x.city),country=ipaNormText(x.country);
   return city&&address.includes(city)&&(!country||address.includes(country));
  });
  if(cityMatched.length===1)return cityMatched[0];
 }
 return null; // never guess when ambiguous
}

function ipaCatalogPhotoSyncReport(total,trips,unmatched,examples=[],failed=0){
 const box=document.querySelector('#catalogPhotoSyncReport');if(!box)return;
 box.hidden=false;
 box.innerHTML=`<b>Resultado da vinculação</b><span>${total} fotos enviadas às viagens · ${trips} viagens atualizadas · ${unmatched} passeios sem foto ou associação · ${failed} erro(s) de gravação.</span>${examples.length?`<small>Exemplos para conferir: ${examples.map(ipaEscape).join(' · ')}</small>`:''}<small>Se houver foto vinculada, mas ela não aparecer no cliente, use “Testar imagem do Google” para verificar o serviço de fotos.</small>`;
}
async function ipaTestPlacePhotoEndpoint(){
 const box=document.querySelector('#catalogPhotoSyncReport');
 const candidate=(adminData().placeCatalog||[]).find(p=>p.photoUrl);
 if(!candidate){toast('O catálogo não possui fotos para testar.');return}
 box.hidden=false;box.innerHTML='<b>Testando foto do Google Places...</b>';
 const url=candidate.photoUrl;
 const image=new Image();
 image.onload=()=>{box.innerHTML=`<b>✓ Foto abriu neste navegador</b><small>${ipaEscape(candidate.name)}. Se ainda não aparecer no login do cliente, verifique a vinculação às viagens.</small>`};
 image.onerror=()=>{box.innerHTML=`<b>⚠️ URL da foto não carregou</b><small>${ipaEscape(candidate.name)} · ${ipaEscape(url)}. Verifique a rota /api/places/photo, a chave Google Maps e se a API Places (New) está habilitada no ambiente publicado.</small>`};
 image.src=url;
}
async function ipaSyncExistingCatalogPhotos(){
 const btn=document.querySelector('#catalogPhotosToTrips');
 if(!window.IPAFirebase?.user){toast('Entre como ADM para sincronizar as fotos.');return}
 const data=adminData(),catalog=(data.placeCatalog||[]).filter(x=>x.photoUrl);
 if(!catalog.length){toast('Nenhuma foto disponível no Banco de Lugares.');return}
 let total=0,updatedTrips=0,unmatched=0,failed=0;const missingExamples=[];
 const changes=[];
 for(const trip of data.trips||[]){
  if(!Array.isArray(trip.itinerary))continue;
  let count=0;
  const itinerary=trip.itinerary.map(day=>{
   if(!Array.isArray(day.places))return day;
   return {...day,places:day.places.map(p=>{
    if(typeof p!=='object'||!p)return p;
    if(p.photoUrl)return p;
    const hit=ipaPhotoCatalogMatch(p,catalog);
    if(!hit?.photoUrl){unmatched++;if(missingExamples.length<8)missingExamples.push(p.name||'Passeio sem nome');return p}
    count++;return {...p,photoUrl:hit.photoUrl,catalogPlaceId:p.catalogPlaceId||hit.id,placeId:p.placeId||hit.placeId||''};
   })};
  });
  if(count)changes.push({id:trip.id,itinerary,count});
 }
 if(!changes.length){ipaCatalogPhotoSyncReport(0,0,unmatched,missingExamples);toast(`Nenhuma foto nova. ${unmatched} passeio(s) sem foto ou associação.`);return}
 if(btn){btn.disabled=true;btn.textContent='Sincronizando fotos...'}
 try{
  for(const [i,item] of changes.entries()){
   if(btn)btn.textContent=`Sincronizando ${i+1}/${changes.length} viagens...`;
   try{
    await window.IPAFirebase.saveTripItineraryPhotos(item.id,item.itinerary);
    IPAData.updateTrip(item.id,{itinerary:item.itinerary});
    total+=item.count;updatedTrips++;
   }catch(err){failed++;console.error('Erro ao gravar fotos no roteiro',item.id,err)}
  }
  ipaCatalogPhotoSyncReport(total,updatedTrips,unmatched,missingExamples,failed);toast(`${total} foto(s) gravada(s) em ${updatedTrips} viagem(ns). Consulte o relatório abaixo.`);
 }finally{
  if(btn){btn.disabled=false;btn.textContent='🖼️ Aplicar fotos nos roteiros'}
 }
}
function ipaUpdateRoutePhotosForCatalog(place,photoUrl){
 const updates=[];
 for(const trip of adminData().trips||[]){
  if(!Array.isArray(trip.itinerary))continue;
  let dirty=false;
  const itinerary=trip.itinerary.map(day=>{
   if(!Array.isArray(day.places))return day;
   const places=day.places.map(p=>{
    const linked=String(p.catalogPlaceId||'')===String(place.id)||!!(place.placeId&&p.placeId===place.placeId);
    // Para lugares antigos sem vínculo, exigir nome E endereço iguais.
    const legacy=!linked&&!p.catalogPlaceId&&!p.placeId&&ipaNormText(p.name)===ipaNormText(place.name)&&!!p.address&&ipaNormText(p.address)===ipaNormText(place.address);
    if(!(linked||legacy)||p.photoUrl)return p;
    dirty=true;return {...p,photoUrl};
   });return dirty?{...day,places}:day;
  });
  if(dirty)updates.push({tripId:trip.id,itinerary});
 }
 return updates;
}
async function ipaStartCatalogPhotoBatch(){
 if(ipaCatalogPhotoJob?.running)return;
 if(!window.IPAFirebase?.user){toast('Entre como administrador para atualizar as fotos.');return}
 const queue=(adminData().placeCatalog||[]).filter(p=>!p.photoUrl&&p.photoLookupStatus!=='not-found').slice(0,25);
 if(!queue.length){toast('Nenhum lugar pendente. Os que não têm imagem disponível foram marcados para revisão.');return}
 const job={running:true,paused:false,total:queue.length,done:0,found:0,noPhoto:0,errors:0,current:'Iniciando consultas…'};
 ipaCatalogPhotoJob=job;ipaCatalogPhotoFeedback(job);
 const btn=document.querySelector('#catalogPhotoBatch');if(btn)btn.disabled=true;
 const changedTrips=new Map();
 for(const p of queue){
  if(!job.running)break;
  job.current=p.name+' · '+[p.city,p.country].filter(Boolean).join(', ');ipaCatalogPhotoFeedback(job);
  try{
   const hit=await ipaCatalogPhotoLookup(p);
   if(hit?.photoUrl){
    const current=(adminData().placeCatalog||[]).find(x=>String(x.id)===String(p.id));
    if(current&&!current.photoUrl){
     const patch={photoUrl:hit.photoUrl,placeId:current.placeId||hit.id||'',photoUpdatedAt:new Date().toISOString()};
     // Confirmação remota ANTES de considerar a foto concluída.
     const stored=await window.IPAFirebase.saveCatalogPhoto(p.id,patch);
     if(stored){IPAData.updateCatalogPlace(p.id,patch);job.found++;}
     const linked=ipaUpdateRoutePhotosForCatalog({...current,...patch},hit.photoUrl);
     linked.forEach(t=>changedTrips.set(t.tripId,t.itinerary));
    }
   }else{
    await window.IPAFirebase.saveCatalogPhoto(p.id,{photoLookupStatus:'not-found',photoCheckedAt:new Date().toISOString()});
    IPAData.updateCatalogPlace(p.id,{photoLookupStatus:'not-found',photoCheckedAt:new Date().toISOString()});
    job.noPhoto++;
   }
  }catch(err){job.errors++;console.warn('Foto não atualizada',p.name,err);job.current='Falha em '+p.name+': '+(err.message||'erro')}
  job.done++;ipaCatalogPhotoFeedback(job);
  // Pequena pausa: evita disparar centenas de consultas simultâneas.
  await new Promise(resolve=>setTimeout(resolve,250));
 }
 job.current='Gravando fotos nos roteiros das viagens existentes…';ipaCatalogPhotoFeedback(job);
 for(const [tripId,itinerary] of changedTrips){
  try{await window.IPAFirebase.saveTripItineraryPhotos(tripId,itinerary);IPAData.updateTrip(tripId,{itinerary})}
  catch(err){job.errors++;console.error('Não foi possível atualizar o roteiro',tripId,err)}
 }
 job.running=false;job.current=job.paused?'Lote interrompido. As fotos já gravadas foram preservadas.':'Pode executar outro lote para continuar de onde parou.';
 ipaCatalogPhotoFeedback(job);
 if(btn)btn.disabled=false;
 toast(`Lote finalizado: ${job.found} fotos salvas, ${job.noPhoto} sem foto, ${job.errors} erros.`);
 // Atualiza somente as miniaturas; não apaga o histórico de progresso.
 document.querySelectorAll('[data-catalog-card]').forEach(card=>{
  const id=card.dataset.catalogId;const p=(adminData().placeCatalog||[]).find(x=>x.id===id);
  if(p?.photoUrl){const old=card.querySelector('.ipa-catalog-thumbnail');if(old)old.outerHTML=ipaPlacePhotoHtml(p,'ipa-catalog-thumbnail')}
 });
}
function ipaBindCatalogTools(){
 const search=document.querySelector('#catalogSearch'),filter=document.querySelector('#catalogGeoFilter');
 const apply=()=>{const q=ipaNormText(search?.value),f=filter?.value||'all';document.querySelectorAll('[data-catalog-card]').forEach(card=>{const match=(!q||ipaNormText(card.dataset.search).includes(q))&&(f==='all'||card.dataset.geo===f);card.style.display=match?'':'none'});const hint=document.querySelector('#catalogDuplicateHint');if(hint)hint.textContent=q?`${[...document.querySelectorAll('[data-catalog-card]')].filter(x=>x.style.display!=='none').length} resultado(s) no banco.`:''};
 if(search)search.oninput=apply;if(filter)filter.onchange=apply;
 document.querySelectorAll('[data-admin-locate-place]').forEach(btn=>btn.onclick=async()=>{const p=(adminData().placeCatalog||[]).find(x=>x.id===btn.dataset.adminLocatePlace);if(!p)return;btn.disabled=true;btn.textContent='Localizando...';try{await ipaLocateCatalogPlace(p);if(window.IPAFirebase?.user)await window.IPAFirebase.syncNow();toast('Localização atualizada ✓');render()}catch(e){toast(e.message||'Não foi possível localizar');btn.disabled=false;btn.textContent='📍 Atualizar localização'}});
 const testPhoto=document.querySelector('#catalogPhotoTest');if(testPhoto)testPhoto.onclick=ipaTestPlacePhotoEndpoint;
 const photoBatch=document.querySelector('#catalogPhotoBatch');if(photoBatch)photoBatch.onclick=ipaStartCatalogPhotoBatch;
 const photoStop=document.querySelector('#catalogPhotoStop');if(photoStop)photoStop.onclick=()=>{if(ipaCatalogPhotoJob?.running){ipaCatalogPhotoJob.running=false;ipaCatalogPhotoJob.paused=true;ipaCatalogPhotoJob.current='Interrompendo após a consulta atual…';ipaCatalogPhotoFeedback(ipaCatalogPhotoJob)}};
 if(ipaCatalogPhotoJob)ipaCatalogPhotoFeedback(ipaCatalogPhotoJob);
 const bulk=document.querySelector('#catalogLocateMissing');if(bulk)bulk.onclick=async()=>{const missing=(adminData().placeCatalog||[]).filter(p=>!Number.isFinite(Number(p.lat))||!Number.isFinite(Number(p.lng)));if(!missing.length)return toast('Todos os lugares já têm localização ✓');bulk.disabled=true;let ok=0;for(const p of missing){bulk.textContent=`📍 Localizando ${ok+1}/${missing.length}...`;try{await ipaLocateCatalogPlace(p);ok++}catch(e){console.warn('Localização pendente',p.name,e)}}try{if(window.IPAFirebase?.user)await window.IPAFirebase.syncNow()}catch{}toast(`${ok} de ${missing.length} lugares localizados ✓`);render()};
}
// Beta 6.29.85 — event delegation survives ADM rerenders and Firebase refreshes.
// Always reorder the source suggestion, never a detached DOM copy.
let ipaLeadDrag=null;
let ipaLeadMoving=false;
async function ipaMoveSuggestedPlace(leadId,dayNum,fromIndex,toIndex){
 if(ipaLeadMoving)return;
 const lead=(adminData().travelLeads||[]).find(l=>String(l.id)===String(leadId));
 const source=lead?.adminSuggestion;
 const day=(source?.days||[]).find(x=>Number(x.day)===Number(dayNum));
 const from=Number(fromIndex),to=Number(toIndex);
 if(!day||!Array.isArray(day.places)||!Number.isInteger(from)||!Number.isInteger(to)||from<0||to<0||from>=day.places.length||to>=day.places.length||from===to)return;
 ipaLeadMoving=true;
 try{
  const updated=JSON.parse(JSON.stringify(source));
  const edited=updated.days.find(x=>Number(x.day)===Number(dayNum));
  edited.places.splice(to,0,edited.places.splice(from,1)[0]);
  IPAData.updateTravelLead(lead.id,{adminSuggestion:updated});
  const region=[...document.querySelectorAll('[data-lead-result]')].find(el=>el.dataset.leadResult===String(lead.id));
  if(region){
   region.innerHTML=ipaAdminSuggestionHtml({...lead,adminSuggestion:updated},updated);
   // Focus is restored after drawing, so clicking an arrow never looks inert.
   const focus=region.querySelector(`[data-lead-place][data-day="${Number(dayNum)}"][data-place-index="${to}"] [data-lead-grip]`);
   focus?.focus({preventScroll:true});
  }
  if(window.IPAFirebase?.saveLeadSuggestionConfirmed){
   try{await window.IPAFirebase.saveLeadSuggestionConfirmed(lead.id)}catch(e){console.error('Falha ao gravar nova ordem',e);toast('Ordem ajustada. Falha ao salvar no Firebase: '+(e?.message||'erro de conexão'))}
  }else{toast('Ordem ajustada. Verifique a conexão com o Firebase antes de sair da tela.')}
 }finally{ipaLeadMoving=false}
}
function ipaLeadTargetAt(clientY,source){
 if(!source)return null;
 const rows=[...document.querySelectorAll('[data-lead-place]')].filter(el=>el.dataset.leadPlace===source.leadId&&el.dataset.day===source.day);
 let closest=null,distance=Infinity;
 for(const el of rows){const r=el.getBoundingClientRect();const delta=Math.abs(clientY-(r.top+r.height/2));if(delta<distance){distance=delta;closest=el}}
 return closest;
}
// Capture phase intentionally intercepts the earlier direct button handlers.
// The DOM for Pedidos is frequently rebuilt, so delegation is critical.
document.addEventListener('click',ev=>{
 const arrow=ev.target.closest?.('[data-lead-move]');
 if(!arrow)return;
 ev.preventDefault();ev.stopImmediatePropagation();
 if(arrow.disabled)return;
 const from=Number(arrow.dataset.placeIndex),to=from+(arrow.dataset.direction==='up'?-1:1);
 void ipaMoveSuggestedPlace(arrow.dataset.leadMove,arrow.dataset.day,from,to);
},true);
document.addEventListener('pointerdown',ev=>{
 const grip=ev.target.closest?.('[data-lead-grip]');if(!grip||ev.button>0)return;
 const row=grip.closest('[data-lead-place]');if(!row)return;
 ipaLeadDrag={leadId:row.dataset.leadPlace,day:row.dataset.day,from:Number(row.dataset.placeIndex),pointerId:ev.pointerId,startY:ev.clientY,lastY:ev.clientY,moved:false,grip};
 row.classList.add('ipa-lead-dragging');
 try{grip.setPointerCapture(ev.pointerId)}catch(_e){}
},true);
document.addEventListener('pointermove',ev=>{
 const d=ipaLeadDrag;if(!d||d.pointerId!==ev.pointerId)return;
 d.lastY=ev.clientY;
 if(Math.abs(ev.clientY-d.startY)>6){d.moved=true;ev.preventDefault()}
}, {capture:true,passive:false});
document.addEventListener('pointerup',ev=>{
 const d=ipaLeadDrag;if(!d||d.pointerId!==ev.pointerId)return;
 ipaLeadDrag=null;
 document.querySelectorAll('.ipa-lead-dragging').forEach(row=>row.classList.remove('ipa-lead-dragging'));
 if(!d.moved)return;
 const target=ipaLeadTargetAt(ev.clientY,d);
 if(target)void ipaMoveSuggestedPlace(d.leadId,d.day,d.from,Number(target.dataset.placeIndex));
},true);
document.addEventListener('pointercancel',()=>{ipaLeadDrag=null;document.querySelectorAll('.ipa-lead-dragging').forEach(row=>row.classList.remove('ipa-lead-dragging'))},true);
let ipaLeadNativeDrag=null;
document.addEventListener('dragstart',ev=>{
 const row=ev.target.closest?.('[data-lead-place]');if(!row)return;
 ipaLeadNativeDrag={leadId:row.dataset.leadPlace,day:row.dataset.day,from:Number(row.dataset.placeIndex)};
 if(ev.dataTransfer){ev.dataTransfer.effectAllowed='move';ev.dataTransfer.setData('text/plain','reorder-trip-suggestion')}
},true);
document.addEventListener('dragover',ev=>{if(ipaLeadNativeDrag&&ev.target.closest?.('[data-lead-place]'))ev.preventDefault()},true);
document.addEventListener('drop',ev=>{
 if(!ipaLeadNativeDrag)return;
 const row=ev.target.closest?.('[data-lead-place]');const d=ipaLeadNativeDrag;ipaLeadNativeDrag=null;
 if(!row||row.dataset.leadPlace!==d.leadId||row.dataset.day!==d.day)return;
 ev.preventDefault();ev.stopImmediatePropagation();
 void ipaMoveSuggestedPlace(d.leadId,d.day,d.from,Number(row.dataset.placeIndex));
},true);
document.addEventListener('dragend',()=>{ipaLeadNativeDrag=null},true);
// Beta 6.29.87: Pedidos recria a lista ao ordenar os lugares.
// Delegação permanente evita perder o botão de criação ao trocar innerHTML.
async function ipaCreateLeadTripFromButton(btn){
   if(btn.disabled)return;
   const leadId=btn.dataset.leadCreateTrip;
   const d=adminData(),lead=(d.travelLeads||[]).find(x=>String(x.id)===String(leadId));
   const note=document.createElement('div');note.className='ipa-lead-save-status';note.setAttribute('role','status');note.setAttribute('aria-live','polite');
   btn.parentElement?.appendChild(note);
   const progress=(message,kind='pending')=>{note.textContent=message;note.dataset.kind=kind;btn.textContent=kind==='error'?'↻ Tentar salvar e seguir para Viagens':'↻ '+message};
   if(!lead?.adminSuggestion){progress('Gere a sugestão antes de criar a viagem','error');return}
   const client=(d.clients||[]).find(c=>c.id===lead.clientId||c.leadId===lead.id||c.requestCode===lead.requestCode||(lead.email&&String(c.email||'').toLowerCase()===String(lead.email).toLowerCase())||(lead.phone&&c.phone===lead.phone));
   if(!client){progress('Cliente não encontrado. Verifique o cadastro em Clientes.','error');return}
   btn.disabled=true;
   progress('Preparando roteiro...');
   try{
     if(!window.IPAFirebase?.saveLeadTripConfirmed)throw new Error('Serviço de gravação indisponível. Atualize a versão do aplicativo.');
     if(!window.IPAFirebase.user)throw new Error('Faça login como ADM antes de salvar.');
     const existing=(d.trips||[]).find(t=>String(t.id)===String(lead.tripId)||String(t.sourceLeadId||'')===String(lead.id));
     let trip=existing;
     if(!trip){
       const itinerary=(lead.adminSuggestion.days||[]).map(day=>({day:Number(day.day),title:`Dia ${day.day}${day.city?' · '+day.city:''}`,city:day.city||'',places:(day.places||[]).map((place,i)=>({...place,id:`trip-place-${Date.now()}-${day.day}-${i}`,catalogPlaceId:place.catalogPlaceId||place.id}))}));
       if(!itinerary.length)throw new Error('Nenhum dia encontrado na sugestão de roteiro.');
       const requestedStages=(Array.isArray(lead.stages)&&lead.stages.length?lead.stages:[{destination:lead.destination,days:lead.days}]).map((x,i)=>({id:'stage-'+Date.now()+'-'+i,order:i+1,destination:x.destination,country:x.country||'',days:Number(x.days)||1}));
       trip=IPAData.createTrip({clientId:client.id,name:`${requestedStages.map(x=>x.destination).join(' → ')} · ${lead.name||client.name}`,destination:requestedStages[0].destination,country:'',stages:requestedStages,plan:client.plan||lead.plan||'Explore',itinerary,favoriteSong:lead.favoriteSong||'',sourceLeadId:lead.id,sourceRequestCode:lead.requestCode,smartRouteApprovedAt:new Date().toISOString(),status:'Em preparação'});
     }
     IPAData.updateClientById(client.id,{activeTripId:trip.id,lastConfiguredTripId:trip.id});
     IPAData.updateTravelLead(lead.id,{tripId:trip.id,status:'Roteiro em preparação'});
     await window.IPAFirebase.saveLeadTripConfirmed({tripId:trip.id,clientId:client.id,leadId:lead.id,onProgress:(stage)=>progress(stage)});
     IPAData.updateTravelLead(lead.id,{tripId:trip.id,tripSaveConfirmedAt:new Date().toISOString(),status:'Roteiro aprovado'});
     progress('Gravação confirmada! Abrindo Viagens...','done');
     modal?.close?.();adminSection='trips';adminTripId=trip.id;state.route='admin';render();
     window.scrollTo({top:0,behavior:'instant'});
     toast('Roteiro salvo no Firebase ✓ Complete os dados em Viagens.');
   }catch(err){
     console.error('Falha na transferência Pedidos → Viagens',err);
     const code=err?.code?` (${err.code})`:'';
     progress('Gravação não confirmada'+code+': '+(err?.message||'erro de conexão')+'. O roteiro continua em Pedidos.','error');
     btn.disabled=false;
   }
 }
document.addEventListener('click',event=>{
 const btn=event.target.closest?.('[data-lead-create-trip]');
 if(!btn)return;
 event.preventDefault();
 if(btn.disabled)return;
 void ipaCreateLeadTripFromButton(btn);
},true);

if(!window.__ipaClimateLinkDelegate){
 window.__ipaClimateLinkDelegate=true;
 document.addEventListener('click',e=>{
  const el=e.target.closest('[data-ipa-climate-card] [data-external-route]');
  if(!el)return;
  e.preventDefault();e.stopImmediatePropagation();
  try{const url=new URL(el.dataset.externalRoute);if(url.protocol!=='https:')return;
   const a=document.createElement('a');a.href=url.href;a.target='_blank';a.rel='noopener noreferrer';document.body.appendChild(a);a.click();a.remove();
  }catch(err){toast('Link de conteúdo inválido.')}
 },true);
}
