 document.querySelectorAll('[data-admin-new-place]').forEach(b=>b.onclick=()=>{
  showModal(`<span class="eyebrow">BANCO DE LUGARES</span><h2>Novo lugar</h2>
  <label>Buscar no Google</label><div class="smart-place-search"><input id="catalogGoogleSearch" class="v2-concierge-input" autocomplete="off" placeholder="Ex.: Torre Eiffel, Museu do Louvre..."><button id="catalogOpenMaps" class="btn btn-light">Maps ↗</button></div>
  <div id="catalogPlaceSuggestions" class="place-suggestions"><small>Digite pelo menos 2 letras. Ao escolher um resultado, nome, endereço, cidade e país serão preenchidos.</small></div>
  <div class="planner-grid"><label>Nome<input id="catalogName" class="v2-concierge-input" placeholder="Nome do lugar"></label><label>Categoria<select id="catalogCategory" class="v2-concierge-input"><option>Atração</option><option>Gastronomia</option><option>Museu</option><option>Natureza</option><option>Compras</option><option>Experiência</option><option>Vida noturna</option><option>Outro</option></select></label><label>Cidade<input id="catalogCity" class="v2-concierge-input"></label><label>País<input id="catalogCountry" class="v2-concierge-input"></label></div>
  <label>Endereço<input id="catalogAddress" class="v2-concierge-input" placeholder="Preenchido pelo Google ou manualmente"></label>
  <div class="planner-grid"><label>Custo por pessoa<input id="catalogCost" type="number" min="0" step=".01" class="v2-concierge-input"></label><label>Moeda<select id="catalogCurrency" class="v2-concierge-input"><option>EUR</option><option>BRL</option><option>USD</option></select></label><label>Duração (min)<input id="catalogDuration" type="number" min="15" step="15" value="120" class="v2-concierge-input"></label><label>Prioridade<select id="catalogPriority" class="v2-concierge-input"><option>Recomendado</option><option>Imperdível</option><option>Opcional</option></select></label></div>
  <label>Interesses relacionados</label><div class="planner-interests" id="catalogInterests">${IPA_INTERESTS.map(x=>`<label><input type="checkbox" value="${x}"> ${x}</label>`).join('')}</div>
  <div class="planner-grid"><label class="route-pro-check"><input id="catalogKids" type="checkbox" checked> 👶 Bom com crianças</label><label>Reserva<select id="catalogReservation" class="v2-concierge-input"><option>Não exige</option><option>Recomendada</option><option>Obrigatória</option></select></label></div>
  <label>Dica Indo por Aí<textarea id="catalogTip" class="rating-text" placeholder="O que torna esse lugar especial?"></textarea></label>
  <div id="catalogPhotoPreview" class="ipa-photo-search-preview">📷 A foto principal aparecerá aqui quando disponível na busca.</div><input id="catalogPhotoUrl" type="hidden"><input id="catalogPlaceId" type="hidden"><input id="catalogMapsUrl" type="hidden"><input id="catalogLat" type="hidden"><input id="catalogLng" type="hidden">
  <button id="saveCatalogPlace" class="btn btn-primary btn-block">Salvar no Banco de Lugares</button>`);
  setTimeout(()=>{
   const q=document.querySelector('#catalogGoogleSearch'),box=document.querySelector('#catalogPlaceSuggestions'),save=document.querySelector('#saveCatalogPlace');
   if(!q||!box||!save)return;
   let timer;
   q.oninput=()=>{clearTimeout(timer);timer=setTimeout(async()=>{
    const text=q.value.trim();if(text.length<2){box.innerHTML='<small>Digite pelo menos 2 letras.</small>';return}
    box.innerHTML='<small>Buscando no Google Places...</small>';
    try{
     const destination=[document.querySelector('#catalogCity')?.value,document.querySelector('#catalogCountry')?.value].filter(Boolean).join(', ');
     const r=await fetch(`/api/places/search?q=${encodeURIComponent(text)}&destination=${encodeURIComponent(destination)}`,{cache:'no-store'});
     const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Não foi possível consultar o Google Places');
     box.innerHTML=(j.places||[]).map(p=>`<button type="button" data-catalog-place='${encodeURIComponent(JSON.stringify(p))}'><b>${ipaEscape(p.name||'')}</b><small>${ipaEscape(p.address||'')}</small>${p.rating?`<em>★ ${p.rating} · ${p.reviews||0} avaliações</em>`:''}</button>`).join('')||'<small>Nenhum resultado. Tente outro termo.</small>';
     box.querySelectorAll('[data-catalog-place]').forEach(item=>item.onclick=()=>{
      const p=JSON.parse(decodeURIComponent(item.dataset.catalogPlace));
      q.value=p.name||'';
      document.querySelector('#catalogName').value=p.name||'';
      document.querySelector('#catalogAddress').value=p.address||'';
      if(p.city)document.querySelector('#catalogCity').value=p.city;
      if(p.country)document.querySelector('#catalogCountry').value=p.country;
      document.querySelector('#catalogPlaceId').value=p.id||'';document.querySelector('#catalogPhotoUrl').value=p.photoUrl||'';document.querySelector('#catalogPhotoPreview').innerHTML=ipaPlacePhotoHtml(p,'ipa-photo-preview');
      document.querySelector('#catalogMapsUrl').value=p.mapsUrl||'';
      document.querySelector('#catalogLat').value=p.lat??'';
      document.querySelector('#catalogLng').value=p.lng??'';
      box.innerHTML=`<div class="selected-place">✓ ${ipaEscape(p.name||'')}<small>${ipaEscape(p.address||'')}</small></div>`;
     });
    }catch(e){console.error('Busca de lugares',e);box.innerHTML=`<small>⚠️ ${ipaEscape(e.message||'Não foi possível buscar agora.')} Você ainda pode preencher os campos manualmente e salvar.</small>`}
   },350)};
   document.querySelector('#catalogOpenMaps').onclick=()=>window.open('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(q.value||document.querySelector('#catalogName').value||''),'_blank');
   save.onclick=async()=>{
    const v=id=>document.querySelector(id)?.value?.trim?.()||'';
    const name=v('#catalogName');if(!name){toast('Informe ou selecione o nome do lugar');return}
    const city=v('#catalogCity'),country=v('#catalogCountry');if(!city||!country){toast('Informe cidade e país');return}
    const dup=ipaFindCatalogDuplicates(name,city);if(dup.length&&!confirm(`Possível local já cadastrado: “${dup[0].name}” em ${dup[0].city}.\n\nDeseja cadastrar mesmo assim?`))return;
    const interests=[...document.querySelectorAll('#catalogInterests input:checked')].map(x=>x.value);
    const payload={name,category:v('#catalogCategory'),city,country,address:v('#catalogAddress'),cost:Number(v('#catalogCost')||0),currency:v('#catalogCurrency'),durationMinutes:Number(v('#catalogDuration')||120),priority:v('#catalogPriority'),interests,kidsFriendly:!!document.querySelector('#catalogKids')?.checked,reservation:v('#catalogReservation'),tip:v('#catalogTip'),photoUrl:v('#catalogPhotoUrl'),placeId:v('#catalogPlaceId'),mapsUrl:v('#catalogMapsUrl'),lat:Number(v('#catalogLat'))||null,lng:Number(v('#catalogLng'))||null};
    try{
     if(!window.IPAFirebase?.user){toast('Entre com seu login ADM antes de salvar.');return}
     if(typeof window.IPAFirebase.createCatalogPlace!=='function')throw new Error('Serviço Firebase desatualizado. Atualize a página.');
     save.disabled=true;save.textContent='Gravando no Firebase...';
     const place={...payload,id:'catalog-'+Date.now()+'-'+Math.random().toString(36).slice(2,8),createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};
     await window.IPAFirebase.createCatalogPlace(place);
     IPAData.addCatalogPlace(place);
     toast('Lugar salvo e confirmado no Firebase ✓');modal.close();adminSection='places';render();
    }catch(e){console.error('Falha ao cadastrar lugar',e);toast('Não foi possível cadastrar: '+(e.message||'Erro de conexão com Firebase'));save.disabled=false;save.textContent='Tentar salvar novamente'}
   };
  },0);
 });
 const openPlanner=document.querySelector('#openTravelPlanner');if(openPlanner)openPlanner.onclick=()=>{showModal(ipaPlannerForm(ipaProspectPlan));setTimeout(()=>ipaBindProspectForm(),0)};
 document.querySelectorAll('[data-choose-prospect-plan]').forEach(btn=>btn.onclick=()=>{ipaProspectPlan=btn.dataset.chooseProspectPlan||'';modal.close();showModal(ipaPlannerForm(ipaProspectPlan));setTimeout(()=>ipaBindProspectForm(),0)});
 document.querySelectorAll('[data-admin-smart-client-trip]').forEach(btn=>btn.onclick=()=>{
  const clients=adminData().clients||[];
  if(!clients.length){toast('Cadastre um cliente primeiro');adminSection='clients';render();return}
  const preferred=btn.dataset.adminSmartClientTrip||'';
  const existingTripId=btn.dataset.smartExistingTrip||'';
  const existingTrip=(adminData().trips||[]).find(t=>t.id===existingTripId);
  showModal(`<div class="smart-planner-layout"><span class="eyebrow">✨ CRIAÇÃO INTELIGENTE · ADM</span><h2>${existingTrip?"Criar roteiro para viagem existente":"Planejar viagem para cliente cadastrado"}</h2><p>${existingTrip?`O roteiro será vinculado a <b>${ipaEscape(existingTrip.name)}</b>, sem criar outra viagem. Os demais dados serão preservados.`:"Use o mesmo motor de curadoria dos pedidos externos, sem criar um pedido fictício."}</p>
   <label>Cliente<select id="smartClient" ${existingTrip?"disabled":""}>${clients.map(c=>`<option value="${ipaEscape(c.id)}" ${c.id===preferred?'selected':''}>${ipaEscape(c.name)} · ${ipaEscape(c.email||'')}</option>`).join('')}</select></label>
   <label>Destino (cidade ou país)<input id="smartDestination" placeholder="Ex.: Lisboa" value="${existingTrip?ipaEscape(existingTrip.destination||""):""}" required></label>
   <div class="smart-client-form-grid"><label>Dias<input id="smartDays" type="number" min="1" max="45" value="5"></label><label>Adultos<input id="smartAdults" type="number" min="1" value="2"></label><label>Crianças<input id="smartChildren" type="number" min="0" value="0"></label><label>Ritmo<select id="smartPace"><option value="equilibrado">Equilibrado</option><option value="leve">Leve</option><option value="intenso">Intenso</option></select></label><label>Orçamento por pessoa<input id="smartBudget" type="number" min="0" value="0"></label><label>Moeda<select id="smartCurrency"><option>EUR</option><option>USD</option><option>BRL</option></select></label></div>
   <label>Interesses (separados por vírgula)<input id="smartInterests" placeholder="Ex.: cultura, gastronomia, natureza"></label>
   <button class="btn btn-primary btn-block" id="smartPreview">✨ Gerar sugestão inteligente</button><div id="smartPreviewResult" aria-live="polite"></div></div>`);
  setTimeout(()=>{const generate=document.querySelector('#smartPreview');if(!generate)return;
   let generated=null,input=null;
   generate.onclick=()=>{
    const value=id=>document.querySelector(id)?.value?.trim()||'';
    input={clientId:value('#smartClient'),destination:value('#smartDestination'),days:Number(value('#smartDays')),adults:Number(value('#smartAdults')),children:Number(value('#smartChildren')),pace:value('#smartPace'),budget:Number(value('#smartBudget')),currency:value('#smartCurrency'),interests:value('#smartInterests').split(',').map(x=>x.trim()).filter(Boolean)};
    if(!input.clientId||!input.destination||!input.days||input.days<1){toast('Informe cliente, destino e quantidade de dias');return}
    generated=ipaGenerateCuratedRoute(input);
    const box=document.querySelector('#smartPreviewResult');
    if(!generated.count){box.innerHTML='<div class="planner-empty"><b>Não encontramos atrações para esse destino no Banco de Lugares.</b><small>Cadastre lugares correspondentes e tente novamente.</small></div>';return}
    box.innerHTML=ipaAdminSuggestionHtml({...input,requestCode:'ADM',id:'',tripId:'preview'},generated).replace(/<div class="lead-actions">[\s\S]*?<\/div><\/div>$/,'</div>')+`<section class="smart-manual-add"><h3>📍 Incluir lugar no roteiro</h3><p>Busque no Banco de Lugares ou cadastre um local manualmente.</p><label>Buscar no Banco de Lugares<input id="smartCatalogSearch" placeholder="Digite o nome, cidade ou país" autocomplete="off"></label><label>Selecionar lugar<select id="smartCatalogSelect"><option value="">Escolha um lugar do banco ou preencha manualmente</option></select></label><small id="smartCatalogInfo" aria-live="polite"></small><label>Nome do lugar<input id="smartManualName" placeholder="Ex.: Castelo de São Jorge"></label><div class="smart-manual-grid"><label>Dia<select id="smartManualDay">${generated.days.map(d=>`<option value="${d.day}">Dia ${d.day}</option>`).join('')}</select></label><label>Categoria<input id="smartManualCategory" placeholder="Ex.: Atração"></label></div><button class="btn btn-light btn-block" id="smartManualAdd" type="button" data-no-save-feedback>+ Incluir lugar no roteiro</button><small id="smartManualFeedback" aria-live="polite"></small><div id="smartManualList"></div></section><button class="btn btn-primary btn-block" id="smartCreateTrip" data-no-save-feedback>${existingTrip?"✓ Vincular roteiro à viagem existente":"✓ Aprovar e criar viagem para este cliente"}</button>`;
    const catalog=adminData().placeCatalog||[];
    const search=document.querySelector('#smartCatalogSearch');
    const select=document.querySelector('#smartCatalogSelect');
    const info=document.querySelector('#smartCatalogInfo');
    const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
    const updateCatalog=()=>{
      const term=norm(search.value);
      const matches=catalog.filter(p=>!term||norm([p.name,p.city,p.country,p.category].join(' ')).includes(term)).slice(0,100);
      select.innerHTML='<option value="">'+(matches.length?'Escolha um lugar do banco ou preencha manualmente':'Nenhum lugar encontrado — use cadastro manual')+'</option>'+matches.map(p=>`<option value="${ipaEscape(p.id)}">${ipaEscape(p.name)} · ${ipaEscape(p.city||'')} · ${ipaEscape(p.country||'')}</option>`).join('');
      info.textContent=catalog.length?`${matches.length} lugar(es) encontrado(s) no acervo`:'Banco de Lugares vazio. Você pode incluir manualmente.';
    };
    search.addEventListener('input',updateCatalog);
    select.addEventListener('change',()=>{
      const place=catalog.find(p=>String(p.id)===select.value);
      if(!place)return;
      document.querySelector('#smartManualName').value=place.name||'';
      document.querySelector('#smartManualCategory').value=place.category||'';
      info.textContent=`✓ ${place.name} · ${place.city||''} ${place.country||''} · ${place.durationMinutes||120} min`;
    });
    updateCatalog();
    document.querySelector('#smartManualAdd').onclick=()=>{
      const name=document.querySelector('#smartManualName').value.trim();
      const day=Number(document.querySelector('#smartManualDay').value);
      const category=document.querySelector('#smartManualCategory').value.trim()||'Atração';
      const feedback=document.querySelector('#smartManualFeedback');
      if(!name){feedback.textContent='Informe o nome do lugar.';return}
      const target=generated.days.find(x=>Number(x.day)===day);if(!target)return;
      if(target.places.some(x=>String(x.name||'').trim().toLowerCase()===name.toLowerCase())){feedback.textContent='Este lugar já está neste dia.';return}
      const selected=catalog.find(p=>String(p.id)===select.value);
      const fromCatalog=selected&&norm(selected.name)===norm(name);
      target.places.push(fromCatalog?{...selected,name,category:category||selected.category,catalogPlaceId:selected.id,manual:true,selectedDay:day}:{name,category,cost:0,currency:generated.currency||input.currency,interests:['Adicionado manualmente'],manual:true,selectedDay:day});
      select.value='';search.value='';updateCatalog();
      document.querySelector('#smartManualName').value='';
      feedback.textContent='✓ Lugar incluído no Dia '+day+'.';
      const li=document.createElement('p');li.textContent='📍 Dia '+day+' · '+name;document.querySelector('#smartManualList').appendChild(li);
    };
    const create=document.querySelector('#smartCreateTrip');create.onclick=async()=>{
      if(create.disabled)return;create.disabled=true;create.innerHTML='<span class="ipa-save-spinner" aria-hidden="true"></span> Salvando roteiro, aguarde...';
      try{
       const client=adminData().clients.find(c=>c.id===input.clientId);if(!client)throw Error('Cliente não encontrado');
       const itinerary=generated.days.map(day=>({day:Number(day.day),title:`Dia ${day.day}`,places:(day.places||[]).map((place,i)=>({...place,id:`trip-place-${Date.now()}-${day.day}-${i}`,catalogPlaceId:place.catalogPlaceId||place.id}))}));
       if(existingTrip){
         if(existingTrip.clientId!==client.id)throw Error('O cliente da viagem foi alterado. Atualize a página.');
         if((existingTrip.itinerary||[]).length&&!confirm('Esta viagem já possui um roteiro. Substituir o roteiro atual pelo novo?')){create.disabled=false;create.textContent='✓ Vincular roteiro à viagem existente';return}
         IPAData.updateTrip(existingTrip.id,{itinerary,smartRouteApprovedAt:new Date().toISOString()});
         if(window.IPAFirebase?.user)await window.IPAFirebase.syncNow();
         modal.close();adminSection='trips';adminTripId=existingTrip.id;render();toast('Roteiro vinculado à viagem existente ✓');return;
       }
       const trip=IPAData.createTrip({clientId:client.id,name:`${input.destination} · ${client.name}`,destination:input.destination,country:'',plan:client.plan||'Explore',itinerary,smartRouteApprovedAt:new Date().toISOString(),status:'Em preparação'});
       IPAData.updateClientById(client.id,{activeTripId:trip.id,lastConfiguredTripId:trip.id});
       if(window.IPAFirebase?.user)await window.IPAFirebase.syncNow();
       modal.close();adminSection='trips';adminTripId=trip.id;render();toast('Viagem criada! Complete os dados e finalize a liberação nesta tela.');
      }catch(err){console.error(err);toast(err.message||'Erro ao criar viagem');create.disabled=false;create.textContent=existingTrip?'✓ Vincular roteiro à viagem existente':'✓ Aprovar e criar viagem para este cliente'}
    };
   };
  },0);
 });
 document.querySelectorAll('[data-lead-generate]').forEach(btn=>btn.onclick=async()=>{const d=adminData(),lead=(d.travelLeads||[]).find(x=>x.id===btn.dataset.leadGenerate);if(!lead)return;const result=ipaGenerateRequestedCityRoute(lead);IPAData.updateTravelLead(lead.id,{adminSuggestion:result,status:'Em análise'});const box=document.querySelector(`[data-lead-result="${lead.id}"]`);if(box)box.innerHTML=ipaAdminSuggestionHtml(lead,result);btn.textContent='↻ Gerar novamente';try{if(window.IPAFirebase?.user)await window.IPAFirebase.syncNow()}catch(e){console.warn(e)};bind()});
