 if(emailTest)emailTest.onclick=async()=>{
   if(emailTest.disabled)return;
   emailTest.disabled=true;emailTest.textContent='Enviando teste...';
   try{
     const firebase=window.IPAFirebase;
     if(!firebase?.user)throw new Error('Entre no ADM para testar o envio.');
     const idToken=await firebase.user.getIdToken();
     const response=await fetch('/api/email/test',{method:'POST',headers:{'authorization':'Bearer '+idToken}});
     const data=await response.json();
     if(!response.ok||!data.ok)throw new Error(data.error||'Falha ao enviar e-mail.');
     toast('Teste enviado para '+data.recipient+' ✓');
     emailTest.textContent='✓ Teste enviado';
   }catch(err){console.error('Resend test',err);toast('E-mail não enviado: '+(err.message||err));emailTest.textContent='✉ Testar e-mail Resend'}
   finally{emailTest.disabled=false}
 };
 document.querySelectorAll('[data-admin-invite-trip]').forEach(b=>b.onclick=async()=>{
   const tripId=b.dataset.adminInviteTrip;
   const clientId=b.dataset.clientId;
   const email=b.dataset.clientEmail;
   if(!email){toast('Cliente sem e-mail cadastrado');return}
   const inviteTrip=adminData().trips.find(t=>t.id===tripId);
   if(!inviteTrip){toast('Viagem não encontrada');return}
   if(inviteTrip.clientId!==clientId){toast('A viagem não pertence a este cliente');return}
   if(inviteTrip.published!==true){toast('Publique a viagem antes de enviar o acesso');return}
   const original=b.textContent;b.disabled=true;b.textContent='Vinculando viagem...';
   try{
     // A viagem selecionada passa a ser a viagem ativa daquele cliente.
     // Assim o cliente não depende do tripId sobreviver no link de autenticação.
     IPAData.updateClientById(clientId,{
       activeTripId:tripId,
       lastInvitedTripId:tripId,
       inviteStatus:'preparing'
     });
     if(window.IPAFirebase?.user) await window.IPAFirebase.syncNow();

     b.textContent='Enviando acesso...';
     await window.IPAFirebase.sendCustomClientInvite(email,clientId,tripId,adminData().clients.find(c=>c.id===clientId)?.name||"Viajante");

     IPAData.updateClientById(clientId,{
       activeTripId:tripId,
       lastInvitedTripId:tripId,
       inviteStatus:'sent',
       inviteSentAt:new Date().toISOString()
     });
     IPAData.updateTrip(tripId,{publicationInviteSentAt:new Date().toISOString(),publicationInviteError:''});
     if(window.IPAFirebase?.user) await window.IPAFirebase.syncNow();

     const inviteResults=[{email:email,status:'enviado',role:'titular'}];
     const unique=new Set([email.trim().toLowerCase()]);
     const participants=(inviteTrip.participants||[]).filter(p=>p.email&&p.status!=='accepted');
     for(const participant of participants){
       const recipient=participant.email.trim().toLowerCase();
       if(unique.has(recipient))continue;
       unique.add(recipient);
       try{
         // Não transmitir o ID do cliente titular a outro usuário.
         await window.IPAFirebase.sendCustomClientInvite(recipient,'',tripId,participant.name||'Viajante');
         participant.inviteStatus='sent';participant.inviteSentAt=new Date().toISOString();
         inviteResults.push({email:recipient,status:'enviado',role:'participante'});
       }catch(e){
         participant.inviteStatus='error';
         inviteResults.push({email:recipient,status:'erro: '+(e?.message||'falha'),role:'participante'});
       }
     }
     if(participants.length){
       IPAData.updateTrip(tripId,{participants:inviteTrip.participants});
       if(window.IPAFirebase?.user)await window.IPAFirebase.syncNow();
     }
     const failures=inviteResults.filter(x=>x.status!=='enviado');
     showModal(`<h2>Resultado do envio</h2><div class="ipa-invite-results">${inviteResults.map(x=>`<div><b>${ipaEscape(x.email)}</b><small>${ipaEscape(x.role)} · ${ipaEscape(x.status)}</small></div>`).join('')}</div><p>${failures.length?failures.length+' convite(s) com erro. Verifique os endereços e reenvie individualmente.':'Convites personalizados enviados pelo Resend.'}</p><button class="btn btn-light btn-block" id="closeInviteResults">Fechar</button>`);
     setTimeout(()=>{const close=document.querySelector('#closeInviteResults');if(close)close.onclick=()=>modal.close()},0);
     toast('Viagem vinculada e acesso enviado ✓');
     b.textContent='✓ Convite enviado';
     setTimeout(()=>{b.disabled=false;b.textContent=original},1800);
   }catch(err){
     console.error(err);
     IPAData.updateTrip(tripId,{publicationInviteError:String(err?.message||err).slice(0,240)});
     try{if(window.IPAFirebase?.user)await window.IPAFirebase.syncNow()}catch(syncErr){console.warn('Falha ao registrar erro do convite',syncErr)}
     toast('Erro no convite: '+(err?.code||err?.message||''));
     b.disabled=false;b.textContent=original;
   }
 });
