 const hotelSearch=document.querySelector('#hotelSearch');if(hotelSearch)hotelSearch.oninput=()=>{const q=hotelSearch.value.trim().toLowerCase();document.querySelectorAll('[data-hotel-search]').forEach(x=>x.style.display=!q||x.dataset.hotelSearch.includes(q)?'grid':'none')};
