let ipaGroupUnsubscribe=null,ipaGroupMessages=[],ipaGroupLoading=false;
function ipaChatTime(v){try{const d=v?.toDate?v.toDate():v?new Date(v):new Date();return d.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}catch(e){return''}}
function ipaEscape(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function ipaRenderGroupMessages(){
 const me=window.IPAFirebase?.user?.uid||'';
 if(ipaGroupLoading&&!ipaGroupMessages.length)return '<div class="ipa-chat-empty">Carregando conversa…</div>';
 if(!ipaGroupMessages.length)return '<div class="ipa-chat-empty">Ainda não há mensagens nesta viagem. Seja o primeiro a falar 👋</div>';
 return ipaGroupMessages.map(m=>`<div class="ipa-chat-row ${m.userUid===me?'mine':''}"><div class="ipa-chat-bubble"><b>${ipaEscape(m.participantName||m.userEmail||'Viajante')}</b><p>${ipaEscape(m.text)}</p><small>${ipaChatTime(m.createdAt)}</small></div></div>`).join('');
}
function ipaStartGroupListener(){
 const t=activeTrip();if(!t?.id||!window.IPAFirebase?.listenTripMessages)return;
 if(ipaGroupUnsubscribe){try{ipaGroupUnsubscribe()}catch(e){}}
 ipaGroupLoading=true;
 ipaGroupUnsubscribe=window.IPAFirebase.listenTripMessages(t.id,rows=>{
   ipaGroupMessages=rows||[];ipaGroupLoading=false;
   if(state.route==='community'&&!state.live){const box=document.querySelector('[data-group-messages]');if(box){box.innerHTML=ipaRenderGroupMessages();box.scrollTop=box.scrollHeight}}
 },()=>{ipaGroupLoading=false});
}
function ipaRealtimeCommunityView(){
 const t=activeTrip();
 return `<section class="community-screen ipa-community-real"><div class="community-hero"><span class="eyebrow">GRUPO DA VIAGEM</span><h1>${ipaEscape(tripDestination(t))}</h1>${ipaParticipantBadge(t)}<p>Converse com os participantes em tempo real.</p></div><div class="ipa-chat-box" data-group-messages>${ipaRenderGroupMessages()}</div><form class="ipa-chat-composer" data-group-form><input data-group-input maxlength="2000" placeholder="Escreva uma mensagem…" autocomplete="off"><button class="btn btn-primary" type="submit">Enviar</button></form></section>`;
}
async function ipaSendCurrentGroupMessage(text){
 const t=activeTrip(),p=ipaCurrentParticipant(t);if(!t?.id)return;
 const optimistic={id:'local-'+Date.now(),tripId:t.id,text,participantId:p?.id||'',participantName:p?.name||window.IPAFirebase?.user?.email||'Viajante',userUid:window.IPAFirebase?.user?.uid||'',createdAt:new Date()};
 ipaGroupMessages.push(optimistic);
 const box=document.querySelector('[data-group-messages]');if(box){box.innerHTML=ipaRenderGroupMessages();box.scrollTop=box.scrollHeight}
 try{await window.IPAFirebase.sendTripMessage({tripId:t.id,text,participantId:p?.id||'',participantName:p?.name||''})}
 catch(e){ipaGroupMessages=ipaGroupMessages.filter(x=>x.id!==optimistic.id);alert('Não foi possível enviar a mensagem. Verifique as regras do Firestore.')}
}
