let adminSection='dashboard';
let adminTripId='trip-portugal-2026';
function ipaDB(){return window.IPAData?IPAData.getAll():null}
function ipaClientTrips(){
 const d=ipaDB()||{};
 const clientId=d.activeClientId||localStorage.getItem('ipa-active-client-id')||'';
 if(state.previewFromAdmin===true){
  return (d.trips||[]).filter(t=>t.clientId===clientId);
 }
 return (d.trips||[]).filter(t=>t.published===true&&(!clientId||t.clientId===clientId));
}
function activeTrip(){
 const d=ipaDB();
 const all=ipaClientTrips();
 const previewTrip=localStorage.getItem('ipa-preview-trip-id');
 if(state.previewFromAdmin===true&&previewTrip){
   const preview=all.find(t=>t.id===previewTrip);
   if(preview)return preview;
 }
 const selected=localStorage.getItem('ipa-active-trip-id');
 return all.find(t=>t.id===selected)||all[0]||null;
}
function ipaSelectClientTrip(id){
 const trip=ipaClientTrips().find(t=>t.id===id);
 if(!trip)return;
 localStorage.setItem('ipa-active-trip-id',trip.id);
 state.tripDay=Number((trip.itinerary||[])[0]?.day||1);
 state.mode='before';
 state.live=false;
 state.route='trip';
 ipaSaveClientPage();
 render();
}
function ipaTripCities(t){
 const stages=tripStages(t);
 const cities=stages.map(x=>String(x.destination||'').trim()).filter(Boolean);
 if(cities.length)return [...new Set(cities)];
 return [tripDestination(t)];
}
function ipaTripStatus(t){
 const today=new Date().toISOString().slice(0,10);
 if(t.startDate&&today<t.startDate)return 'Próxima viagem';
 if(t.endDate&&today>t.endDate)return 'Viagem realizada';
 return 'Em andamento';
}
function ipaTripSwitchSection(){
 const trips=ipaClientTrips(),current=activeTrip();
 if(trips.length<2)return '';
 return `<section class="section ipa-my-trips-section"><div class="section-head"><div><span class="eyebrow">Suas experiências</span><h2>Minhas Viagens</h2></div><span class="chip">${trips.length} viagens</span></div>
 <div class="ipa-my-trips-grid">${trips.map(t=>{
  const countries=[...new Set(tripStages(t).map(st=>st.country).filter(Boolean))];
  const cities=ipaTripCities(t);
  const selected=t.id===current?.id;
  return `<button type="button" class="ipa-my-trip-card ${selected?'active':''}" data-client-switch-trip="${ipaEscape(t.id)}" aria-pressed="${selected}">
   <span class="ipa-my-trip-flags">${countries.map(countryFlag).join(' ')||countryFlag(tripCountry(t))}</span>
   <span class="ipa-my-trip-copy"><b>${ipaEscape(t.name||'Minha viagem')}</b><small>${ipaEscape([t.startDate,t.endDate].filter(Boolean).map(d=>{const [y,m,day]=d.split('-');return day+'/'+m+'/'+y}).join(' – '))}</small><span class="ipa-my-trip-cities">${cities.map(ipaEscape).join(' → ')}</span><em>${ipaTripStatus(t)}</em></span>
   <span class="ipa-my-trip-arrow">${selected?'✓':'›'}</span>
  </button>`}).join('')}</div></section>`;
}
function ipaDayCity(t,day){
 const stages=tripStages(t);
 const date=String(day?.date||'');
 const stage=date?stages.find(x=>x.startDate&&x.endDate&&date>=x.startDate&&date<=x.endDate):null;
 return String(day?.city||day?.destination||stage?.destination||'').trim();
}

const PLAN_INCLUDED_LABELS={
 Explore:["Roteiro no app","Pagamentos","Álbum da viagem","Filme da viagem"],
 Signature:["Tudo do Explore","Suporte pré-embarque","Documentos e mala","Check-in","Compra de hotel e passagens"],
 Elite:["Tudo do Signature","Câmbio / Exchange","Comunidade","Live","Passaporte","Acesso full à plataforma"],
 Groups:["Roteiro para grupos","Pré-embarque","Comunidade do grupo","Live","Álbum e filme compartilhados","Gestão de grupos"]
};
function packageIncluded(plan){return PLAN_INCLUDED_LABELS[plan]||PLAN_INCLUDED_LABELS.Explore}

function countryFlag(country){
 const map={"Portugal":"🇵🇹","Brasil":"🇧🇷","Espanha":"🇪🇸","França":"🇫🇷","Itália":"🇮🇹","Reino Unido":"🇬🇧","Inglaterra":"🇬🇧","Estados Unidos":"🇺🇸","Argentina":"🇦🇷","Alemanha":"🇩🇪","Holanda":"🇳🇱","Países Baixos":"🇳🇱","Suíça":"🇨🇭","Áustria":"🇦🇹","Grécia":"🇬🇷","Irlanda":"🇮🇪","Bélgica":"🇧🇪","Croácia":"🇭🇷","Japão":"🇯🇵","Canadá":"🇨🇦","México":"🇲🇽","Chile":"🇨🇱","Uruguai":"🇺🇾"};
 return map[String(country||"").trim()]||"🌍";
}
function countryFlagCode(country){
 const map={"Portugal":"pt","Brasil":"br","Espanha":"es","França":"fr","Itália":"it","Reino Unido":"gb","Inglaterra":"gb","Estados Unidos":"us","Argentina":"ar","Alemanha":"de","Holanda":"nl","Países Baixos":"nl","Suíça":"ch","Áustria":"at","Grécia":"gr","Irlanda":"ie","Bélgica":"be","Croácia":"hr","Japão":"jp","Canadá":"ca","México":"mx","Chile":"cl","Uruguai":"uy"};
 return map[String(country||"").trim()]||"";
}
function countryFlagMarkup(country){const code=countryFlagCode(country);return code?`<img src="https://flagcdn.com/40x30/${code}.png" alt="${ipaEscape(country)}" loading="lazy" referrerpolicy="no-referrer">`:countryFlag(country)}
function tripCountry(t){
 if(t?.country)return t.country;
 const txt=String(t?.destination||"");
 const parts=txt.split(",").map(x=>x.trim());
 return parts.length>1?parts[parts.length-1]:"";
}
function tripStages(t){const a=Array.isArray(t?.stages)?t.stages.filter(Boolean):[];return a.length?a:[{id:"stage-legacy",destination:tripDestinationLegacy(t),country:tripCountry(t),startDate:t?.startDate||"",endDate:t?.endDate||"",order:1}]}
function tripDestinationLegacy(t){return String(t?.destination||t?.name||"Seu destino").split(",")[0].trim()}
function activeTripStage(t,date=new Date()){const stages=tripStages(t);const ymd=date.toISOString().slice(0,10);return stages.find(x=>x.startDate&&x.endDate&&ymd>=x.startDate&&ymd<=x.endDate)||stages.find(x=>x.startDate&&ymd<x.startDate)||stages[stages.length-1]}
function tripDestination(t){return String(activeTripStage(t)?.destination||tripDestinationLegacy(t)).split(",")[0].trim()}
function ipaFindCatalogPlace(place){
 const list=(ipaDB()?.placeCatalog||[]).filter(Boolean);
 if(!place)return null;
 const catalogId=String(place.catalogPlaceId||place.catalogId||'');
 if(catalogId){
  const byCatalog=list.find(x=>String(x.id||'')===catalogId);
  if(byCatalog)return byCatalog;
 }
 const googleId=String(place.placeId||'');
 if(googleId){
  const byPlaceId=list.find(x=>String(x.placeId||'')===googleId);
  if(byPlaceId)return byPlaceId;
 }
 const name=ipaNormText(place.name),address=ipaNormText(place.address),city=ipaNormText(place.city);
 return list.find(x=>{
  const sameName=name&&ipaNormText(x.name)===name;
  const sameAddress=address&&ipaNormText(x.address)===address;
  const sameCity=!city||ipaNormText(x.city)===city;
  return (sameName&&(sameAddress||sameCity))||(sameAddress&&sameCity);
 })||null;
}
function ipaDecorateCatalogPlace(place){
 const base=place&&typeof place==='object'?place:{name:String(place||'')};
 const hit=ipaFindCatalogPlace(base)||{};
 return {...hit,...base,photoUrl:base.photoUrl||hit.photoUrl||'',mapsUrl:base.mapsUrl||hit.mapsUrl||'',placeId:base.placeId||hit.placeId||'',catalogPlaceId:base.catalogPlaceId||hit.id||base.catalogPlaceId||'',smartTip:base.smartTip||base.tip||hit.tip||'',note:base.note||hit.note||''};
}
function normalizedPlaces(day){
 return (day?.places||[]).map((p,i)=>ipaDecorateCatalogPlace(typeof p==='string'?{id:'p-'+day.day+'-'+i,name:p,address:p,time:'',note:''}:p));
}
function googleMapsRouteUrl(day,t){
 const places=normalizedPlaces(day).filter(p=>p.name||p.address);
 if(!places.length)return "";
 const q=p=>p.placeId?`place_id:${p.placeId}`:(p.address||`${p.name}, ${tripDestination(t)}, ${tripCountry(t)}`);
 if(places.length===1)return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(q(places[0]))}`;
 const first=q(places[0]),last=q(places[places.length-1]);
 const middle=places.slice(1,-1).map(q).join("|");
 return `https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(first)}&destination=${encodeURIComponent(last)}${middle?`&waypoints=${encodeURIComponent(middle)}`:''}&travelmode=walking`;
}
function ipaPlacePhotoHtml(place,cls=''){
 const url=String(place?.photoUrl||(place?.placeId?'/api/places/photo?placeId='+encodeURIComponent(place.placeId):''));
 if(!url)return `<div class="ipa-place-photo-fallback ${cls}" aria-label="Foto não disponível">📍</div>`;
 // Apenas URLs próprias do endpoint protegido ou URLs https; nunca executar HTML de dados remotos.
 if(!url.startsWith('/api/places/photo?placeId=')&&!/^https:\/\//i.test(url))return `<div class="ipa-place-photo-fallback ${cls}">📍</div>`;
 return `<div class="ipa-place-photo ${cls}"><img loading="lazy" src="${ipaEscape(url)}" alt="Foto de ${ipaEscape(place.name||'atração')}" onerror="this.style.display='none';this.parentElement.classList.add('ipa-photo-failed')"><span class="ipa-place-photo-empty">📍</span></div>`;
}
function ipaClientDayPlaces(t,day){
 const official=normalizedPlaces(day);
 const personal=ipaGetPersonalRoute(t,day.day).map((p,i)=>({id:p.id||`personal-${i}`,name:p.name||'Descoberta',address:p.address||'',note:'✨ Adicionado por você',personal:true}));
 const all=[...official,...personal];
 let saved=[];try{saved=JSON.parse(localStorage.getItem('ipa-order-'+(window.IPAFirebase?.user?.uid||'visitor')+'-'+t.id+'-'+day.day)||'[]')}catch(e){}
 if(!Array.isArray(saved)||!saved.length)return all;
 const id=(p,i)=>String(p.id||p.placeId||p.name+'|'+p.address||i);
 return all.map((p,i)=>({p,k:id(p,i)})).sort((a,b)=>{const ia=saved.indexOf(a.k),ib=saved.indexOf(b.k);return (ia<0?9999:ia)-(ib<0?9999:ib)}).map(x=>x.p);
}
function ipaFullClientMapsUrl(places,t){
 const list=places.filter(p=>p.name||p.address).map(p=>[p.name,p.address,tripDestination(t),tripCountry(t)].filter(Boolean).join(', '));
 if(!list.length)return '';
 if(list.length===1)return 'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(list[0]);
 return 'https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(list[0])+'&destination='+encodeURIComponent(list[list.length-1])+(list.length>2?'&waypoints='+encodeURIComponent(list.slice(1,-1).join('|')):'')+'&travelmode=walking';
}
function tripModule(name){const t=activeTrip();return t?.modules?.[name]!==false}
function showPlanDetails(){
 const d=ipaDB();if(!d)return;
 const plan=activeTrip()?.plan||d.client.plan||'Explore';
 const items=d.plans[plan]||[];
 showModal(`<span class="eyebrow">Seu plano</span><h2>Indo por Aí ${plan}</h2><div class="plan-feature-list">${items.map(x=>`<div>✓ <span>${x}</span></div>`).join('')}</div>`);
}
const IPA_PREP_DEFAULTS={
 purchase:['Passagens e reservas conferidas','Hospedagem confirmada','Seguro viagem contratado','Ingressos e passeios organizados'],
 documents:['Passaporte ou documento de viagem válido','Vistos e autorizações necessários','Comprovantes de hospedagem','Passagens e bilhetes salvos','Seguro viagem e documentos importantes'],
 checkin:['Conferir abertura do check-in','Realizar check-in da passagem','Salvar cartão de embarque','Conferir horário e terminal','Verificar bagagem permitida'],
 luggage:['Roupas para o clima do destino','Calçados confortáveis','Itens de higiene pessoal','Medicamentos de uso habitual','Carregadores e adaptadores','Documentos e itens essenciais na bagagem de mão']
};
function ipaPrepSnapshot(section){
 const d=ipaDB(),trip=activeTrip(),original=Array.isArray(d?.prep?.[section])?d.prep[section]:[];
 const items=original.length?original.map(x=>typeof x==='string'?{label:x}:x):(IPA_PREP_DEFAULTS[section]||[]).map(label=>({label,done:false}));
 const email=String(window.IPAFirebase?.user?.email||'').trim().toLowerCase();
 const userKey=window.IPAFirebase?.user?.uid||email||'visitante',tripKey=trip?.id||'sem-viagem';
 const storageKey='ipa-client-prep-v2:'+userKey+':'+tripKey+':'+section;
 const legacyKey='ipa-client-prep:'+userKey+':'+tripKey+':'+section;
 let checked={};try{checked=JSON.parse(localStorage.getItem(storageKey)||'null')||{};
  if(!Object.keys(checked).length){const legacy=JSON.parse(localStorage.getItem(legacyKey)||'{}');items.forEach((x,i)=>{if(Object.prototype.hasOwnProperty.call(legacy,i))checked[String(x.label||i)]=Boolean(legacy[i])})}
 }catch(e){checked={}}
 const itemKey=x=>String(x.label||'').trim();
 const itemDone=(x,i)=>Object.prototype.hasOwnProperty.call(checked,itemKey(x))?Boolean(checked[itemKey(x)]):Boolean(x.done);
 return {items,checked,storageKey,itemKey,itemDone,count:items.filter(itemDone).length,total:items.length};
}
function ipaPrepProgressUpdate(section){
 const p=ipaPrepSnapshot(section);
 document.querySelectorAll('[data-prep-count="'+section+'"]').forEach(el=>{el.textContent=p.count+'/'+p.total+' concluídos'});
 document.querySelectorAll('[data-prep-progress="'+section+'"]').forEach(el=>{el.classList.toggle('done',p.total>0&&p.count===p.total);el.classList.toggle('active',p.count>0&&p.count<p.total)});
}
function ipaPrepJourneyCard(section,icon,title,subtitle){
 const p=ipaPrepSnapshot(section),status=p.total&&p.count===p.total?'done':p.count?'active':'';
 return `<button class="v2-journey-step ${status}" data-no-save-feedback data-prep-section="${section}" data-prep-progress="${section}"><span class="ipa-journey-symbol">${icon}</span><div><b>${title}</b><small>${ipaEscape(subtitle)}</small><small class="ipa-prep-counter" data-prep-count="${section}">${p.count}/${p.total} concluídos</small></div></button>`;
}
function prepChecklist(section,title){
 const d=ipaDB();if(!d)return;
 if(section==='exchange'){
   const e=d.exchange;
   showModal(`<div class="exchange-view"><span class="eyebrow">Indo por Aí Exchange</span><h2>Seu saldo para Portugal</h2><p>O Indo por Aí organiza seu câmbio de forma personalizada.</p><div class="exchange-balance"><small>Saldo reservado</small><strong>€ ${e.requestedEuro}</strong><span>€1 = R$ ${Number(e.sellRate).toFixed(2).replace('.',',')}</span><b>${e.status}</b></div><div class="partner-strip"><small>Benefício em parceria com</small><strong>${e.partner}</strong></div><button class="btn btn-primary btn-block" onclick="toast('Solicitação enviada ao Indo por Aí');modal.close()">Falar sobre meu câmbio</button></div>`);
   return;
 }
 const {items,checked,storageKey,itemKey,itemDone}=ipaPrepSnapshot(section);
 showModal(`<span class="eyebrow">Preparação da viagem</span><h2>${ipaEscape(title||section)}</h2><p>Marque cada item. Seu progresso é salvo automaticamente neste navegador.</p><div class="prep-checklist">${items.map((x,i)=>`<label><input type="checkbox" data-prep-index="${i}" ${itemDone(x,i)?'checked':''}><span>${ipaEscape(x.label||'Item '+(i+1))}</span></label>`).join('')}</div><small id="ipa-prep-saved" role="status" aria-live="polite">${items.filter((x,i)=>itemDone(x,i)).length} de ${items.length} concluídos</small>`);
 const persist=()=>{
  try{
   localStorage.setItem(storageKey,JSON.stringify(checked));
   const verified=JSON.parse(localStorage.getItem(storageKey)||'{}');
   if(JSON.stringify(verified)!==JSON.stringify(checked))throw Error('Falha de verificação');
   const count=items.filter((x,i)=>itemDone(x,i)).length;
   ipaPrepProgressUpdate(section);
   const feedback=modalContent.querySelector('#ipa-prep-saved');
   if(feedback){feedback.textContent='✓ Salvo · '+count+' de '+items.length+' concluídos';feedback.style.color='#16805a'}
  }catch(e){console.error('Erro ao gravar checklist',e);const feedback=modalContent.querySelector('#ipa-prep-saved');if(feedback){feedback.textContent='Não foi possível salvar neste navegador.';feedback.style.color='#b33a35'};toast('Não foi possível salvar checklist neste dispositivo')}
 };
 modalContent.querySelectorAll('[data-prep-index]').forEach(cb=>cb.addEventListener('change',()=>{
   checked[itemKey(items[Number(cb.dataset.prepIndex)])]=cb.checked;
   persist();
 }));
 // Persist migrated checklist and show state immediately on reopening.
 if(Object.keys(checked).length)persist();

}
function benefitsPersonalized(){
 const d=ipaDB();if(!d)return'';
 const active=d.benefits.filter(x=>x.enabled);
 return `<section class="section"><div class="section-head"><div><span class="eyebrow">Personalizado para você</span><h2>Benefícios exclusivos</h2></div><span class="chip">${active.length} ativos</span></div><div class="benefit-market">${active.map(b=>`<button class="benefit-market-card" data-benefit-id="${b.id}"><div><span class="eyebrow">${b.sponsorLabel}</span><h3>${b.title}</h3><p>${b.partner}</p></div><span>›</span></button>`).join('')}</div></section>`;
}
