function brl(v){return new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(v||0))}
function paymentSummary(){
 const d=ipaDB();if(!d)return'';
 const total=d.payments.reduce((s,p)=>s+p.amount,0);
 const paid=d.payments.filter(p=>p.status==='Pago').reduce((s,p)=>s+p.amount,0);
 const pending=total-paid;
 return {total,paid,pending};
}
function openPayment(id){
 const d=ipaDB();const p=d?.payments.find(x=>x.id===id);if(!p)return;
 if(p.status==='Pago'){
   showModal(`<span class="eyebrow">Pagamento</span><h2>${p.title}</h2><div class="payment-paid-card"><span>✓</span><strong>Pagamento confirmado${p.paymentEnvironment==='test'?' (teste)':''}</strong><small>${brl(p.amount)} · ${p.paidAt||''}</small></div><p>${p.description}</p><button class="btn btn-light btn-block" onclick="toast('Comprovante disponível');modal.close()">Ver comprovante</button>`);
   return;
 }
 showModal(`<div class="payment-modal"><span class="eyebrow">Pagamento disponível</span><h2>${p.title}</h2><p>${p.description}</p><div class="payment-amount">${brl(p.amount)}</div><small>Vencimento: ${new Date(p.dueDate+'T12:00:00').toLocaleDateString('pt-BR')}</small><div class="payment-methods"><button data-pay-method="pix:${p.id}"><span>◈</span><b>Pagar com Pix</b><small>Abra o app do seu banco</small></button><button data-pay-method="card:${p.id}"><span>💳</span><b>Pagar com cartão</b><small>Checkout seguro</small></button></div><p class="payment-safe">🔒 Os dados do cartão não ficam armazenados no Indo por Aí.</p></div>`);
 setTimeout(()=>document.querySelectorAll('[data-pay-method]').forEach(btn=>btn.onclick=()=>simulatePayment(btn.dataset.payMethod)),0);
}
function simulatePayment(payload){
 const [method,id]=payload.split(':');
 const d=ipaDB();
 const p=d?.payments.find(x=>x.id===id);
 if(!p)return;

 if(method==='pix'){
   createMercadoPagoPix(p);
   return;
 }

 openMercadoPagoCard(p);
}

let ipaCardForm=null;
async function openMercadoPagoCard(payment){
 const client=currentPaymentClient();
 const safeEmail=String(client?.email||'').replace(/"/g,'&quot;');
 showModal(`<div class="card-real-modal">
   <div class="payment-brand"><img src="assets/logo-inline.png" alt="Indo por Aí"><div><span class="eyebrow">CARTÃO · MERCADO PAGO</span><h2>Pagamento seguro</h2></div></div>
   <div class="card-charge"><small>Valor da cobrança</small><strong>${brl(payment.amount)}</strong><span>🔒 Processado pelo Mercado Pago</span></div>
   <form id="form-checkout" class="mp-card-form">
    <label>Número do cartão<div id="form-checkout__cardNumber" class="mp-secure-field"></div></label>
    <div class="mp-card-row"><label>Validade<div id="form-checkout__expirationDate" class="mp-secure-field"></div></label><label>CVV<div id="form-checkout__securityCode" class="mp-secure-field"></div></label></div>
    <label>Nome no cartão<input type="text" id="form-checkout__cardholderName" autocomplete="cc-name" placeholder="Como está no cartão"></label>
    <label>Emissor<select id="form-checkout__issuer"></select></label>
    <label>Parcelamento<select id="form-checkout__installments"></select></label>
    <div class="mp-card-row"><label>Documento<select id="form-checkout__identificationType"></select></label><label>Número<input type="text" id="form-checkout__identificationNumber" inputmode="numeric" placeholder="CPF"></label></div>
    <label>E-mail<input type="email" id="form-checkout__cardholderEmail" value="${safeEmail}" autocomplete="email"></label>
    <button type="submit" id="form-checkout__submit" class="btn btn-primary btn-block">Pagar ${brl(payment.amount)}</button>
    <progress value="0" class="mp-progress">Carregando...</progress>
   </form>
   <p class="payment-safe">🔒 Número, validade e CVV são tokenizados pelo Mercado Pago e não ficam armazenados no Indo por Aí.</p>
 </div>`);
 try{
   if(!window.MercadoPago)throw new Error('MercadoPago.js não carregou. Verifique sua conexão.');
   const keyResponse=await fetch('/api/payments/public-key',{cache:'no-store'});
   const keyData=await keyResponse.json().catch(()=>({}));
   if(!keyResponse.ok||!keyData.publicKey)throw new Error(keyData.error||'Public Key do Mercado Pago indisponível.');
   const mp=new MercadoPago(keyData.publicKey,{locale:'pt-BR'});
   ipaCardForm=mp.cardForm({
    amount:String(Number(payment.amount||0).toFixed(2)),iframe:true,
    form:{id:'form-checkout',cardNumber:{id:'form-checkout__cardNumber',placeholder:'Número do cartão'},expirationDate:{id:'form-checkout__expirationDate',placeholder:'MM/AA'},securityCode:{id:'form-checkout__securityCode',placeholder:'CVV'},cardholderName:{id:'form-checkout__cardholderName',placeholder:'Nome no cartão'},issuer:{id:'form-checkout__issuer',placeholder:'Emissor'},installments:{id:'form-checkout__installments',placeholder:'Parcelas'},identificationType:{id:'form-checkout__identificationType',placeholder:'Tipo'},identificationNumber:{id:'form-checkout__identificationNumber',placeholder:'Documento'},cardholderEmail:{id:'form-checkout__cardholderEmail',placeholder:'E-mail'}},
    callbacks:{
     onFormMounted:error=>{if(error){console.error('Mercado Pago CardForm',error);toast('Não foi possível carregar o cartão');}},
     onSubmit:event=>{event.preventDefault();processMercadoPagoCard(payment,ipaCardForm);},
     onFetching:()=>{const bar=document.querySelector('.mp-progress');bar?.removeAttribute('value');return()=>bar?.setAttribute('value','0');}
    }
   });
 }catch(err){console.error(err);showCardStatusModal('error','configuração',String(err?.message||err),'');}
}

async function processMercadoPagoCard(payment,cardForm){
 const submit=document.querySelector('#form-checkout__submit');
 try{
   if(submit){submit.disabled=true;submit.textContent='Processando...';}
   const data=cardForm.getCardFormData();
   if(!data.token)throw new Error('Confira os dados do cartão.');
   const response=await fetch('/api/payments/card',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({paymentId:payment.id,amount:Number(payment.amount||0),description:payment.title||payment.description||'Cobrança Indo por Aí',token:data.token,payment_method_id:data.paymentMethodId,issuer_id:data.issuerId,installments:Number(data.installments||1),payer:{email:data.cardholderEmail,identification:{type:data.identificationType,number:data.identificationNumber}}})});
   const result=await response.json().catch(()=>({}));
   if(!response.ok||!result.ok)throw new Error(result?.error||result?.details?.message||`Erro ${response.status}`);
   const status=String(result.paymentStatus||'').toLowerCase();
   IPAData.updatePayment(payment.id,{mpPaymentId:result.paymentId,mpStatus:status,mpStatusDetail:result.paymentStatusDetail,paymentMethodId:result.paymentMethodId,installments:result.installments,paymentEnvironment:'production'});
   if(['approved','processed','paid'].includes(status)){IPAData.updatePayment(payment.id,{status:'Pago',paidAt:new Date().toISOString().slice(0,10)});if(window.IPAFirebase?.user)await window.IPAFirebase.syncNow().catch(()=>{});showCardStatusModal('approved',status,result.paymentStatusDetail,result.paymentId);return;}
   if(['rejected','cancelled','canceled','expired','failed'].includes(status)){showCardStatusModal('error',status,result.paymentStatusDetail,result.paymentId);return;}
   showCardStatusModal('pending',status,result.paymentStatusDetail,result.paymentId);
 }catch(err){console.error('Mercado Pago cartão',err);showCardStatusModal('error','não aprovado',String(err?.message||err),'');}
 finally{if(submit){submit.disabled=false;submit.textContent=`Pagar ${brl(payment.amount)}`;}}
}

function showCardStatusModal(kind,status,detail,paymentId){
 const ok=kind==='approved',pending=kind==='pending';
 const title=ok?'Pagamento aprovado':pending?'Pagamento em análise':'Pagamento não aprovado';
 const text=ok?'O Mercado Pago confirmou o pagamento.':pending?'O Mercado Pago está analisando o pagamento.':'O pagamento não foi concluído. Confira os dados ou tente outro cartão.';
 showModal(`<div class="pix-status-card pix-status-${ok?'approved':pending?'pending':'error'}"><div class="pix-status-icon">${ok?'✓':pending?'⌛':'!'}</div><span class="eyebrow">CARTÃO · MERCADO PAGO</span><h2>${title}</h2><p>${text}</p><div class="pix-status-grid"><div><small>Status</small><strong>${status||'-'}</strong></div><div><small>Detalhe</small><strong>${detail||'-'}</strong></div></div>${paymentId?`<small class="pix-order-id">Pagamento: ${paymentId}</small>`:''}<button class="btn btn-light btn-block" onclick="modal.close();render()">Voltar</button></div>`);
}


function currentPaymentClient(){
 const d=ipaDB();
 const activeClientId=localStorage.getItem('ipa-active-client-id');
 const trip=activeTrip();
 return (d?.clients||[]).find(c=>c.id===activeClientId)
   ||(d?.clients||[]).find(c=>trip?.clientId&&c.id===trip.clientId)
   ||d?.client||{};
}

function createMercadoPagoPix(payment){
 const client=currentPaymentClient();
 const safeEmail=String(client?.email||'').replace(/"/g,'&quot;');
 showModal(`<div class="pix-real-modal">
   <span class="eyebrow">PIX · MERCADO PAGO</span>
   <h2>Gerar Pix</h2>
   <p>Você vai gerar uma cobrança real de <b>${brl(payment.amount)}</b>.</p>
   <div class="form-grid">
    <label>E-mail do pagador<input id="pixPayerEmail" type="email" value="${safeEmail}" autocomplete="email"></label>
    <label>CPF do pagador<input id="pixPayerCpf" inputmode="numeric" maxlength="14" placeholder="000.000.000-00"></label>
   </div>
   <p class="payment-safe">🔒 O CPF é enviado diretamente ao Mercado Pago para gerar esta cobrança e não é salvo pelo Indo por Aí.</p>
   <button class="btn btn-primary btn-block" id="generateRealPix">Gerar Pix de ${brl(payment.amount)}</button>
   <button class="btn btn-light btn-block" onclick="modal.close()">Cancelar</button>
 </div>`);
 setTimeout(()=>{
   const b=document.querySelector('#generateRealPix'); if(!b)return;
   b.onclick=()=>generateRealPix(payment,b);
 },0);
}

async function generateRealPix(payment,button){
 const email=document.querySelector('#pixPayerEmail')?.value?.trim()||'';
 const cpf=(document.querySelector('#pixPayerCpf')?.value||'').replace(/\D/g,'');
 if(!email||!email.includes('@'))return toast('Informe o e-mail do pagador');
 if(cpf.length!==11)return toast('Informe o CPF com 11 dígitos');
 button.disabled=true;button.textContent='Gerando Pix...';
 try{
   const response=await fetch('/api/payments/pix',{
     method:'POST',headers:{'Content-Type':'application/json'},
     body:JSON.stringify({paymentId:payment.id,amount:Number(payment.amount||0),description:payment.title||payment.description||'Cobrança Indo por Aí',payerEmail:email,payerCpf:cpf})
   });
   const result=await response.json().catch(()=>({}));
   if(!response.ok||!result.ok)throw new Error(result?.error||result?.details?.message||`Erro ${response.status}`);
   IPAData.updatePayment(payment.id,{mpPaymentId:result.paymentId,mpStatus:result.paymentStatus,mpStatusDetail:result.paymentStatusDetail,paymentEnvironment:'production',pixCreatedAt:new Date().toISOString()});
   if(window.IPAFirebase?.user)await window.IPAFirebase.syncNow().catch(()=>{});
   showPixResult(payment,result);
 }catch(err){
   console.error('Mercado Pago PIX',err);
   showModal(`<span class="eyebrow">PIX · Mercado Pago</span><h2>Não conseguimos gerar o Pix</h2><div class="payment-error-box">${String(err?.message||err)}</div><p>Nenhuma cobrança foi marcada como paga. Confira os dados e tente novamente.</p><button class="btn btn-light btn-block" onclick="modal.close()">Fechar</button>`);
 }finally{button.disabled=false;}
}

function showPixResult(payment,result){
 const qrImage=result.qrCodeBase64?`<img class="pix-real-qr" alt="QR Code Pix" src="data:image/png;base64,${result.qrCodeBase64}">`:`<div class="pix-real-qr-placeholder">PIX<br><small>Use o código abaixo</small></div>`;
 showModal(`<div class="pix-real-modal">
   <span class="eyebrow">PIX · MERCADO PAGO</span>
   <h2>Pix gerado</h2>
   <p class="pix-original-charge">Valor: <b>${brl(payment.amount)}</b></p>
   ${qrImage}
   ${result.qrCode?`<label class="pix-copy-label">Pix Copia e Cola</label><div class="pix-copy-row"><textarea id="pixCopyCode" readonly>${result.qrCode}</textarea><button data-copy-pix>Copiar</button></div>`:''}
   ${result.ticketUrl?`<button class="btn btn-primary btn-block" data-open-pix-ticket="${result.ticketUrl}">Abrir pagamento Pix</button>`:''}
   <button class="btn btn-light btn-block" data-check-pix="${payment.id}:${result.paymentId}">Já paguei · verificar</button>
   <small class="pix-order-id">Pagamento Mercado Pago: ${result.paymentId}</small>
 </div>`);
 setTimeout(()=>{
   document.querySelectorAll('[data-copy-pix]').forEach(b=>b.onclick=async()=>{const code=document.querySelector('#pixCopyCode')?.value||'';try{await navigator.clipboard.writeText(code);toast('Pix copiado ✓')}catch{toast('Selecione e copie o código')}});
   document.querySelectorAll('[data-open-pix-ticket]').forEach(b=>b.onclick=()=>window.open(b.dataset.openPixTicket,'_blank'));
   document.querySelectorAll('[data-check-pix]').forEach(b=>b.onclick=()=>{const [paymentId,mpPaymentId]=b.dataset.checkPix.split(':');checkMercadoPagoPix(paymentId,mpPaymentId,b)});
 },0);
}

async function checkMercadoPagoPix(paymentId,mpPaymentId,button){
 const original=button.textContent;button.disabled=true;button.textContent='Consultando...';
 try{
   const response=await fetch(`/api/payments/pix/status?paymentId=${encodeURIComponent(mpPaymentId)}`,{cache:'no-store'});
   const result=await response.json().catch(()=>({}));
   if(!response.ok||!result.ok)throw new Error(result?.error||`Erro ${response.status}`);
   const status=String(result.paymentStatus||'').toLowerCase(),detail=String(result.paymentStatusDetail||'').toLowerCase();
   IPAData.updatePayment(paymentId,{mpStatus:status,mpStatusDetail:detail});
   if(['approved','processed','paid'].includes(status)){
     IPAData.updatePayment(paymentId,{status:'Pago',paidAt:new Date().toISOString().slice(0,10),paymentEnvironment:'production'});
     if(window.IPAFirebase?.user)await window.IPAFirebase.syncNow().catch(()=>{});
     showPixStatusModal('approved',status,detail,mpPaymentId);return;
   }
   if(['rejected','cancelled','canceled','expired','failed'].includes(status)){showPixStatusModal('error',status,detail,mpPaymentId);return;}
   showPixStatusModal('pending',status,detail,mpPaymentId);
 }catch(err){console.error(err);showPixStatusModal('error','erro_consulta',String(err?.message||''),mpPaymentId)}
 finally{button.disabled=false;button.textContent=original;}
}

function showPixStatusModal(kind,status,detail,paymentId){
 const ok=kind==='approved',err=kind==='error';
 const title=ok?'Pagamento confirmado':err?'Não foi possível confirmar':'Aguardando pagamento';
 const text=ok?'O Mercado Pago confirmou o Pix. A cobrança foi marcada como paga.':err?'O Mercado Pago retornou erro, recusa ou expiração para esta cobrança.':'O Pix ainda está pendente no Mercado Pago. Depois do pagamento, consulte novamente.';
 showModal(`<div class="pix-status-card pix-status-${kind}"><div class="pix-status-icon">${ok?'✓':err?'!':'⌛'}</div><span class="eyebrow">PIX · MERCADO PAGO</span><h2>${title}</h2><p>${text}</p><div class="pix-status-grid"><div><small>Status</small><strong>${status||'sem status'}</strong></div><div><small>Detalhe</small><strong>${detail||'sem detalhe'}</strong></div></div><small class="pix-order-id">Pagamento: ${paymentId}</small><button class="btn btn-light btn-block" onclick="modal.close();render()">Voltar</button></div>`);
}

function paymentsView(){
 const d=ipaDB(),t=activeTrip();
 const payments=(d.payments||[]).filter(p=>!t||p.tripId===t.id||(!p.tripId&&p.trip===t.name));
 const total=payments.reduce((s,p)=>s+Number(p.amount||0),0);
 const paid=payments.filter(p=>p.status==='Pago').reduce((s,p)=>s+Number(p.amount||0),0);
 const pending=total-paid;
 return `<section class="payments-hero"><span class="eyebrow">Minha Viagem</span><h1>Pagamentos</h1><p>${t?.name||'Sua viagem'} · acompanhe parcelas, extras e comprovantes.</p><div class="payment-summary-grid"><div><small>Contratado</small><strong>${brl(total)}</strong></div><div><small>Pago</small><strong>${brl(paid)}</strong></div><div><small>Em aberto</small><strong>${brl(pending)}</strong></div></div></section>
 <section class="section"><div class="section-head"><h2>Suas cobranças</h2><span class="chip">${payments.length} lançamento(s)</span></div><div class="payment-list">${payments.map(p=>`<button class="payment-row" data-payment="${p.id}"><div class="payment-status ${p.status==='Pago'?'paid':'pending'}">${p.status==='Pago'?'✓':'!'}</div><div><span class="eyebrow">${p.trip||t?.name||''}</span><h3>${p.title}</h3><p>${p.description}</p><small>Vencimento ${p.dueDate?new Date(p.dueDate+'T12:00:00').toLocaleDateString('pt-BR'):'-'}</small></div><div class="payment-row-value"><strong>${brl(p.amount)}</strong><span class="${p.status==='Pago'?'paid-text':'pending-text'}">${p.status}</span></div></button>`).join('')||'<div class="empty-payment-state"><span>💳</span><b>Nenhuma cobrança pendente</b><small>Quando o Indo por Aí enviar uma cobrança, ela aparecerá aqui.</small></div>'}</div></section>`;
}


