async function handleClientEmailInvite(){
 if(!window.IPAFirebase?.isEmailSignInLink?.()) return false;

 let email=localStorage.getItem("ipa-email-for-signin")||"";
 if(!email) email=window.prompt("Confirme o e-mail que recebeu o convite:")||"";
 if(!email) return false;

 try{
   state.scenarioChosen=true;
   state.profile='client';
   state.mode='before';
   state.route='today';
   document.body.classList.add('hidden-nav');
   view.innerHTML=`<section class="client-login-loading"><span>✈️</span><h2>Preparando sua viagem...</h2><p>Estamos carregando sua experiência personalizada.</p></section>`;

   await window.IPAFirebase.completeEmailLink(email);
   showClientPasswordSetup();
   return true;
 }catch(err){
   console.error(err);
   document.body.classList.remove('hidden-nav');
   toast('Não foi possível concluir o acesso: '+(err?.code||err?.message||''));
   showInitialScenario();
   return false;
 }
}
window.addEventListener('ipa-firebase-service-loaded',()=>{handleClientEmailInvite()});
window.addEventListener('ipa-client-password-setup',()=>{if(window.IPAFirebase?.user)showClientPasswordSetup()});

if(!(window.IPAFirebase?.isEmailSignInLink?.())){
  // O Firebase é módulo e pode ainda não ter carregado neste ponto.
  // A tela inicial só é mostrada agora; se já houver sessão de cliente,
  // o onAuthStateChanged a substituirá pela experiência personalizada.
  showInitialScenario();
}


function ipaMovieMemories(t){
 const raw=[...(ipaDB().memories||[]).filter(m=>m.tripId===t?.id),...ipaPendingMovieItems(t)];
 return raw.map((m,i)=>({
   ...m,
   media:m.url||m.src||m.remote||m.media||'',
   caption:m.prompt||m.caption||m.placeName||'Momento da viagem',
   placeName:m.placeName||m.place||'',
   participantName:m.participantName||'',
   featured:!!m.featured,
   day:Number(m.day||1),
   date:m.createdAt||m.date||'',
   isVideo:m.type==='video'||String(m.type||'').startsWith('video')
 })).filter(m=>m.media).sort((a,b)=>{
   if(a.day!==b.day)return a.day-b.day;
   return String(a.date).localeCompare(String(b.date));
 });
}
function ipaMovieDates(t){
 const f=v=>{if(!v)return'';try{return new Date(v+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'})}catch(e){return v}};
 return [f(t?.startDate),f(t?.endDate)].filter(Boolean).join(' — ');
}
function ipaMovieTravelers(t){
 const names=(t?.participants||[]).map(p=>p.name).filter(Boolean);
 return names.length?names.join(' · '):'Uma história para guardar';
}
function ipaMovieStageName(t,m){
 const stages=t?.stages||t?.destinations||t?.cities||[];
 const stage=Array.isArray(stages)?stages.find(x=>Number(m.day)>=Number(x.startDay||x.dayStart||1)&&Number(m.day)<=Number(x.endDay||x.dayEnd||999)):null;
 return String(stage?.city||stage?.destination||m.city||m.destination||'').trim();
}
