function ipaMovieMusicEngine(){
 const tracks={emotional:'emocionante',light:'leve',upbeat:'animada'};
 let el=null,attempt=0;
 const stop=()=>{++attempt;if(el){el.pause();el.removeAttribute('src');el.load();el=null}};
 const start=async(style)=>{
   stop();if(style==='off')return true;
   const ticket=attempt;
   const name=tracks[style]||tracks.emotional;
   const audio=document.createElement('audio');el=audio;
   audio.loop=true;audio.volume=.65;audio.preload='auto';audio.playsInline=true;
   const formats=audio.canPlayType('audio/mp4')?['m4a','mp3']:['mp3','m4a'];
   for(const ext of formats){
     if(ticket!==attempt)return false;
     audio.src=new URL('assets/trilha-'+name+'.'+ext,document.baseURI).href;
     try{await audio.play();return !audio.paused}catch(e){
       console.warn('Falha ao reproduzir trilha '+name+'.'+ext,e);
       if(e?.name==='NotAllowedError')return false;
     }
   }
   return false;
 };
 const volume=v=>{if(el)el.volume=Math.max(0,Math.min(1,Number(v)||0))};
 return {start,stop,volume};
}

function ipaBindMovie2(){
 const root=document.querySelector('.movie3-shell');if(!root)return;
 const els=[...root.querySelectorAll('[data-movie2-scene]')],bar=root.querySelector('[data-movie2-progress]');
 const plays=[...root.querySelectorAll('[data-movie2-play]')],audio=ipaMovieMusicEngine();
 const music=root.querySelector('[data-movie3-music]'),format=root.querySelector('[data-movie3-format]'),audioStatus=root.querySelector('[data-movie3-audio-status]');
 let i=0,timer=null,playing=false,startTime=0,duration=0,remaining=0,raf=0,disposed=false;
 const sceneDuration=()=>{const v=els[i]?.querySelector('video');return v&&Number.isFinite(v.duration)&&v.duration>0?Math.min(Math.max(v.duration*1000,4000),8000):(i===0||i===els.length-1?3000:3600)};
 const stopVideo=()=>els.forEach(x=>{const v=x.querySelector('video');if(v){try{v.pause()}catch(e){}}});
 const updateBar=()=>{if(disposed)return;const pct=Math.max(0,Math.min(1,(performance.now()-startTime)/duration));if(bar)bar.style.width=`${100*(i+pct)/els.length}%`;if(playing)raf=requestAnimationFrame(updateBar)};
 const paint=(reset=true)=>{
   stopVideo();els.forEach((x,n)=>x.classList.toggle('active',n===i));
   const v=els[i]?.querySelector('video');if(v&&playing){try{if(reset)v.currentTime=0;v.play().catch(()=>{})}catch(e){}}
   plays.forEach(b=>b.textContent=playing?'⏸ Pausar':'▶ Assistir');
   if(bar)bar.style.width=`${100*i/els.length}%`;
 };
 const schedule=(keep=false)=>{
   clearTimeout(timer);cancelAnimationFrame(raf);if(!playing)return;
   duration=keep?remaining:sceneDuration();startTime=performance.now();updateBar();
   timer=setTimeout(()=>{if(i>=els.length-1){playing=false;audio.stop();i=0;paint();return}i++;paint();schedule()},duration);
 };
 const pause=()=>{if(!playing)return;remaining=Math.max(150,duration-(performance.now()-startTime));playing=false;clearTimeout(timer);cancelAnimationFrame(raf);audio.stop();const v=els[i]?.querySelector('video');if(v)try{v.pause()}catch(e){};plays.forEach(b=>b.textContent='▶ Continuar')};
 const resume=()=>{playing=true;audio.start(music.value).then(ok=>{if(audioStatus)audioStatus.textContent=ok?(music.value==='off'?'Sem música':'♫ Trilha tocando'):'Não foi possível iniciar a trilha. Toque em Testar música.';});paint(false);schedule(remaining>0);remaining=0};
 plays.forEach(b=>b.onclick=()=>playing?pause():resume());
 root.querySelector('[data-movie2-next]').onclick=()=>{i=(i+1)%els.length;remaining=0;paint();schedule()};
 root.querySelector('[data-movie2-prev]').onclick=()=>{i=(i-1+els.length)%els.length;remaining=0;paint();schedule()};
 root.querySelectorAll('[data-movie3-goto]').forEach(b=>b.onclick=()=>{i=Math.max(0,Math.min(els.length-1,Number(b.dataset.movie3Goto)));remaining=0;paint();schedule()});
 music.onchange=()=>{if(playing)audio.start(music.value).then(ok=>{if(audioStatus)audioStatus.textContent=ok?'♫ Trilha tocando':'Trilha indisponível. Toque em Testar música.'})};
 const soundTest=root.querySelector('[data-movie3-test-sound]');if(soundTest)soundTest.onclick=()=>{if(music.value==='off')music.value='light';audio.start(music.value).then(ok=>{if(audioStatus)audioStatus.textContent=ok?'♫ Áudio ligado':'O navegador bloqueou o som. Verifique o volume e toque novamente.'})};
 format.onchange=()=>root.classList.toggle('movie3-vertical',format.value==='vertical');
 const dispose=()=>{disposed=true;clearTimeout(timer);cancelAnimationFrame(raf);audio.stop();stopVideo();modal.removeEventListener('close',dispose)};
 modal.addEventListener('close',dispose);
 paint();
}
function showMemoryDay(dayNumber){
 const t=activeTrip();if(!t)return;
 const day=(t.itinerary||[]).find(d=>Number(d.day)===Number(dayNumber));if(!day)return;
 const mem=(ipaDB().memories||[]).filter(m=>m.tripId===t.id&&Number(m.day||0)===Number(day.day));
 const places=normalizedPlaces(day);
 const title=`Dia ${Number(day.day)}${day.title?' · '+String(day.title):''}`;
 const media=mem.map(m=>m.type==='video'
  ?`<article class="ipa-day-real-memory"><video controls playsinline preload="metadata" src="${ipaEscape(m.src||m.url||'')}"></video><small>${ipaEscape(m.prompt||m.caption||'Vídeo da viagem')}</small></article>`
  :`<article class="ipa-day-real-memory"><img loading="lazy" src="${ipaEscape(m.src||m.url||'')}" alt="${ipaEscape(m.prompt||'Foto da viagem')}"><small>${ipaEscape(m.prompt||m.caption||'Foto da viagem')}</small></article>`).join('');
 showModal(`<div class="memory-day-modal"><span class="eyebrow">ÁLBUM DE LEMBRANÇAS</span><h2>${ipaEscape(title)}</h2><p>${mem.length} memória${mem.length===1?'':'s'} registrada${mem.length===1?'':'s'} · ${places.length} lugar${places.length===1?'':'es'} no roteiro</p>${media?`<div class="ipa-day-real-grid">${media}</div>`:'<p>As fotos e os vídeos registrados neste dia aparecerão aqui automaticamente.</p>'}${places.length?`<h3>Lugares do dia</h3><div class="ipa-day-place-list">${places.map(p=>`<div>📍 ${ipaEscape(p.name||'Lugar visitado')}</div>`).join('')}</div>`:''}</div>`);
}


function showJourneyRating(tripId,dayNo,placeId,placeName){
  const d=ipaDB(),key=[tripId,dayNo,placeId].join(':'),current=d.journeyPlaces?.[key]||{};
  const currentRating=Number(current.rating||0);
  showModal(`<span class="eyebrow">SUA EXPERIÊNCIA</span>
    <h2>Como foi ${placeName}?</h2>
    <p class="rating-help">Toque nas estrelas para dar sua nota.</p>
    <div class="star-picker" role="radiogroup" aria-label="Avaliação de 1 a 5 estrelas">
      ${[1,2,3,4,5].map(n=>`<button type="button" class="${n<=currentRating?'selected':''}" data-journey-star="${n}" aria-label="${n} estrela${n>1?'s':''}" aria-pressed="${n<=currentRating?'true':'false'}">★</button>`).join('')}
    </div>
    <div id="journeyRatingValue" class="rating-value">${currentRating?`${currentRating}/5`:'Selecione uma nota'}</div>
    <textarea id="journeyRatingNote" class="rating-text" placeholder="Conte em poucas palavras...">${current.note||''}</textarea>
    <button type="button" id="saveJourneyRating" class="btn btn-primary btn-block" ${currentRating?'':'disabled'}>Salvar avaliação</button>`);

  setTimeout(()=>{
    let chosen=currentRating;
    const stars=[...document.querySelectorAll('[data-journey-star]')];
    const save=document.querySelector('#saveJourneyRating');
    const label=document.querySelector('#journeyRatingValue');

    const paint=()=>{
      stars.forEach(star=>{
        const n=Number(star.dataset.journeyStar);
        const on=n<=chosen;
        star.classList.toggle('selected',on);
        star.setAttribute('aria-pressed',on?'true':'false');
      });
      if(label)label.textContent=chosen?`${chosen}/5`:'Selecione uma nota';
      if(save)save.disabled=!chosen;
    };

    stars.forEach(star=>{
      const choose=(ev)=>{
        ev.preventDefault();
        ev.stopPropagation();
        chosen=Number(star.dataset.journeyStar);
        paint();
      };
      star.onclick=choose;
      star.ontouchend=choose;
    });

    paint();

    if(save){
      save.onclick=async(ev)=>{
        ev.preventDefault();
        if(!chosen){toast('Selecione de 1 a 5 estrelas');return}
        const note=document.querySelector('#journeyRatingNote')?.value.trim()||'';
        IPAData.saveJourneyPlace(tripId,dayNo,placeId,{rating:chosen,note});
        // Atualização visual síncrona: não depende do Firebase nem de trocar de tela.
        // Atualiza o card que já está no DOM antes de fechar o modal. Não depende de render nem do Firebase.
        ipaPaintJourneyStarsNow(tripId,dayNo,placeId,chosen);
        toast(`Avaliação ${chosen}★ salva ✓`);
        modal.close();
        requestAnimationFrame(()=>ipaPaintJourneyStarsNow(tripId,dayNo,placeId,chosen));
        // Firebase sincroniza sem bloquear a tela.
        if(window.IPAFirebase?.user && window.IPAFirebase?.syncNow){
          window.IPAFirebase.syncNow().catch(e=>console.warn('Avaliação salva localmente; sincronização pendente',e));
        }
      };
    }
  },40);
}
